"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser, assertNotImpersonating } from "./auth";
import { InsufficientBalanceError } from "./wallet";
import { diskExpandQuote, applyDiskExpand, DiskExpandError } from "./disk-expand";
import { createDiskExpandCheckout, type EmbeddedCheckout } from "./stripe";
import { walletSplit } from "./wallet-split";
import { normalizeExtraDiskGB } from "./extra-disk";
import { emailVerificationError } from "./email-verification";

/**
 * Post-deploy "Add storage": grow ONE server's own root disk by N GB without
 * changing its plan (CPU/RAM/plan price are untouched).
 *
 * Money path is a carbon copy of lib/actions-server.ts resizeServer:
 *   quote -> walletSplit -> (card remainder ? Stripe checkout : apply now).
 * The wallet is only ever debited by applyDiskExpand, and only after the card
 * portion has cleared, so displayed === charged and nothing is charged twice.
 *
 * GROWTH IS ONE-WAY. There is deliberately no companion "shrink" action.
 */

/** Max expansions a single customer may start in RATE_WINDOW_MS. */
const MAX_EXPANDS_PER_WINDOW = 5;
const RATE_WINDOW_MS = 10 * 60_000;

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

export async function expandServerDisk(
  serverId: string,
  addGB: number,
  useWallet: boolean = true,
): Promise<{ error?: string; checkout?: EmbeddedCheckout }> {
  // Spend path: block wallet debits while an admin is impersonating.
  await assertNotImpersonating();
  const { user, server } = await ownedServer(serverId);
  // Purchase gate: a disk expansion is an irreversible charge.
  // See lib/email-verification.ts.
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };

  // Round DOWN to a purchasable amount — a malformed value can only ever cost
  // the customer less, never more (see normalizeExtraDiskGB).
  const gb = normalizeExtraDiskGB(addGB);
  if (gb <= 0) return { error: "Choose an amount of storage to add." };

  // Rate limit: expansions are irreversible and each one queues real hypervisor
  // work, so cap how fast a single account can fire them off.
  const recent = await db.job.count({
    where: {
      type: "DISK_EXPAND",
      createdAt: { gt: new Date(Date.now() - RATE_WINDOW_MS) },
      server: { userId: user.id },
    },
  });
  if (recent >= MAX_EXPANDS_PER_WINDOW) {
    return { error: "Too many storage expansions just now — please wait a few minutes and try again." };
  }

  // Reject while another job is in flight, and only from a steady run state.
  // (applyDiskExpand re-checks both; this returns the friendlier message first.)
  if (!["RUNNING", "STOPPED"].includes(server.status)) {
    return { error: "Server must be running or stopped to add storage." };
  }
  const pending = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
  });
  if (pending > 0) return { error: "Another operation is already in progress on this server." };

  // Validate + price the expansion (ownership already checked above).
  let quote;
  try {
    quote = await diskExpandQuote(serverId, gb);
  } catch (e) {
    if (e instanceof DiskExpandError) return { error: e.message };
    throw e;
  }
  const { prorateCents } = quote;

  // Wallet-aware split — identical logic to the deploy/resize flows. AddStorage
  // computes the same split (lib/wallet-split.ts) so displayed === charged.
  const { cardCents } = walletSplit({
    dueCents: prorateCents,
    balanceCents: user.balanceCents,
    useWallet,
  });

  // Card portion > 0 → charge ONLY the remainder on the card. The confirm route
  // credits the card amount to the wallet and then debits the FULL proration
  // (encoded as chargeCents), so the wallet absorbs its share and the card the
  // rest — the wallet is never touched before the card clears.
  if (cardCents > 0) {
    const checkout = await createDiskExpandCheckout(user, cardCents, {
      serverId,
      addGB: gb,
      hostname: server.hostname,
      prorateCents,
    });
    if (!checkout) {
      return {
        error: `Adding ${gb} GB costs $${(prorateCents / 100).toFixed(2)} for the rest of your term, and card payments aren't set up — top up your wallet first.`,
      };
    }
    return { checkout };
  }

  // Card portion is $0 (wallet fully covers it, or the charge is $0 for free/admin
  // servers) → apply instantly, debiting the full proration from the wallet.
  try {
    await applyDiskExpand({ serverId, addGB: gb, actorUserId: user.id });
  } catch (e) {
    if (e instanceof DiskExpandError) return { error: e.message };
    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
    throw e;
  }
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

