/**
 * A cents amount that arrived from OUTSIDE this process (Stripe metadata) and is
 * about to be handed to `debitWallet`. Integer, non-negative, finite — anything
 * else is refused rather than coerced, for the same reason `parseOrderPrice`
 * refuses a half-valid price: the caller's `?? quote.prorateCents` fallback would
 * silently RE-PRICE the purchase at confirm time, which is the H2 incident.
 */
function parseChargeCents(raw: unknown): number | null {
  if (typeof raw !== "number" || !Number.isInteger(raw) || raw < 0) return null;
  return raw;
}

function parseId(raw: unknown): string | null {
  return typeof raw === "string" && raw.length > 0 ? raw : null;
}

/**
 * WHAT a paid Checkout session was for — the ONE decision that routes fulfilment.
 *
 * REAL DEFECT this shape exists to remove (found 2026-07-27 audit). Fulfilment used
 * to ask three separate `getCheckout*Intent` helpers, each of which did its OWN
 * `sessions.retrieve` inside a `try` that returned `null` on ANY failure. So a
 * transient Stripe error — a 5xx, a rate limit, a dropped socket — turned "I could
 * not read this session" into "this session has no purchase metadata", and
 * `fulfilCheckoutSession` fell through to its plain wallet-top-up branch reporting
 * `fulfilled: true`. Card charged, no server, no `FulfilledSession` row, no
 * notification, and the webhook returns 200 so Stripe never retries. Exactly the
 * class of invisible failure that file was written to end, one layer up.
 *
 * `unreadable` and `unpaid` are therefore first-class answers, NOT absences. The
 * session is retrieved exactly once (`getCheckoutPurpose`, which THROWS rather than
 * returning a lie) and classified by a pure function over its metadata.
 */
export type CheckoutPurpose =
  | {
      kind: "order";
      userId: string;
      intent: OrderIntent;
      sold: OrderPrice | null;
      campaign: string;
      /** The first-month-free hold to confirm at fulfilment; null for a full-price order. */
      promoReservationToken: string | null;
      /** The checkout-coupon hold to confirm at fulfilment; null for a full-price order. */
      couponReservationToken: string | null;
    }
  | {
      kind: "gameOrder";
      userId: string;
      intent: GameOrderIntent;
      /** The price the game order was SOLD at; null only on a malformed stamp. */
      sold: GameOrderPrice | null;
    }
  | { kind: "resize"; userId: string; serverId: string; planId: string; chargeCents: number }
  | { kind: "diskExpand"; userId: string; serverId: string; addGB: number; chargeCents: number }
  /** No purchase metadata: a wallet top-up the customer bought for its own sake. */
  | { kind: "topup"; userId: string | null }
  /** Not paid (or paid to nobody) — nothing to fulfil and nothing to claim. */
  | { kind: "unpaid" }
  /** Purchase metadata IS present but cannot be trusted. Never treat as a top-up. */
  | { kind: "unreadable"; userId: string | null; detail: string };

/**
 * Classify a retrieved session. Pure — no clock, no network, no database — so the
 * routing decision is unit-testable and identical for the redirect and the webhook.
 */
export function classifyCheckoutSession(
  session: Pick<Stripe.Checkout.Session, "metadata" | "payment_status">,
): CheckoutPurpose {
