// / isValidHostingDomain / isValidSubdomainLabel / cron validators) AND re-checked
// in the worker. Caps are enforced inside a Serializable transaction so concurrent
// creates cannot both read a stale count and blow past the plan (same discipline
// as createHostingDatabase). The task is queued in the SAME tx as the row create.

const SITE_STATES = ["PENDING", "ACTIVE"] as const;
const MAX_CRON_JOBS = 20;

/** Owner (or admin) + ACTIVE account, returning the fields the site actions need. */
async function ownedSiteAccount(id: string) {
  const user = await requireUser();
  // Impersonating admins must not create/destroy customer resources — cron is
  // arbitrary command execution as the customer's unix user; subdomains/addons
  // mint live vhosts. Matches createHostingAccount/createHostingDatabase (audit MED-3).
  await assertNotImpersonating();
  const a = await db.hostingAccount.findUnique({
    where: { id },
    select: { id: true, userId: true, status: true, username: true, primaryDomain: true, maxSites: true },
  });
  if (!a) return { error: "Account not found." as const };
  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." as const };
  if (a.status !== "ACTIVE") return { error: "The account is still being set up." as const };
  return { user, a };
}

/**
 * Is this hostname already claimed ANYWHERE? A shared node routes purely by nginx
 * `server_name`, and a hostname can live in THREE places — a primary domain, a
 * subdomain, or an addon domain. Before this, each creator only checked its own
 * table, so an addon could shadow a victim's subdomain (or vice-versa) on a
 * co-located node = cross-tenant vhost takeover (security audit HIGH-1/HIGH-2).
 *
 * This is now a FAST, FRIENDLY PRE-CHECK only — good UX (an early, clear error)
 * but NOT trusted alone: a non-atomic read can't stop two concurrent requests
 * from both passing it and both committing the same server_name (the co-tenant
 * vhost-shadowing TOCTOU). The authoritative guard is the atomic UNIQUE(hostname)
 * insert into HostingHostnameClaim done INSIDE each creator's transaction — a
 * colliding claim fails there (P2002) and rolls the whole tx back.
 */
async function isHostnameClaimed(name: string): Promise<boolean> {
  // The authoritative registry (single UNIQUE(hostname) spanning all three kinds)
  // is the fast, definitive pre-check now. We also still scan the three resource
  // tables so any legacy row created before the claims table existed is honoured.
  const host = normalizeClaimHostname(name);
  const [claim, prim, sub, addon] = await Promise.all([
    db.hostingHostnameClaim.count({ where: { hostname: host } }),
    db.hostingAccount.count({ where: { primaryDomain: name, status: { in: [...LIVE_STATES] } } }),
    db.hostingSubdomain.count({ where: { fqdn: name, status: { in: [...SITE_STATES] } } }),
    db.hostingAddonDomain.count({ where: { domain: name, status: { in: [...SITE_STATES] } } }),
  ]);
  return claim + prim + sub + addon > 0;
}

/** True when an error is a Prisma unique-constraint violation (P2002). A colliding
 *  hostname claim surfaces here — the atomic guard that replaces trusting the read. */
function isUniqueViolation(e: unknown): boolean {
  return (e as { code?: string })?.code === "P2002";
}

export type HostingSubdomainView = { id: string; label: string; fqdn: string; sslActive: boolean; status: string; createdAt: string };
export type HostingAddonView = { id: string; domain: string; sslActive: boolean; status: string; createdAt: string };
export type HostingCronView = { id: string; schedule: string; command: string; status: string; createdAt: string };

async function assertSiteOwner(accountId: string): Promise<{ userId: string } | null> {
  const user = await requireUser();
  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true } });
  if (!a) return null;
  if (a.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return a;
}

export async function listHostingSubdomains(accountId: string): Promise<HostingSubdomainView[]> {
  if (!(await assertSiteOwner(accountId))) return [];
  const rows = await db.hostingSubdomain.findMany({ where: { accountId }, orderBy: { createdAt: "desc" } });
  return rows.map((s) => ({ id: s.id, label: s.label, fqdn: s.fqdn, sslActive: s.sslActive, status: s.status, createdAt: s.createdAt.toISOString() }));
}

export async function listHostingAddonDomains(accountId: string): Promise<HostingAddonView[]> {
  if (!(await assertSiteOwner(accountId))) return [];
  const rows = await db.hostingAddonDomain.findMany({ where: { accountId }, orderBy: { createdAt: "desc" } });
  return rows.map((d) => ({ id: d.id, domain: d.domain, sslActive: d.sslActive, status: d.status, createdAt: d.createdAt.toISOString() }));
}

export async function listHostingCrons(accountId: string): Promise<HostingCronView[]> {
  if (!(await assertSiteOwner(accountId))) return [];
  const rows = await db.hostingCron.findMany({ where: { accountId }, orderBy: { createdAt: "desc" } });
  return rows.map((c) => ({ id: c.id, schedule: c.schedule, command: c.command, status: c.status, createdAt: c.createdAt.toISOString() }));
}

/** The plan's maxSites budget is shared by subdomains + addon domains (the primary
 *  domain is always live and doesn't consume it). */
function siteCapMessage(maxSites: number): string {
  return `Your plan allows ${maxSites} extra site${maxSites === 1 ? "" : "s"} (subdomains + addon domains).`;
}

export async function createSubdomain(accountId: string, label: string): Promise<HostingResult> {
  const ctx = await ownedSiteAccount(accountId);
  if ("error" in ctx) return { error: ctx.error };
  const { a } = ctx;
  const clean = String(label ?? "").trim().toLowerCase();
  if (!isValidSubdomainLabel(clean)) return { error: "Enter a valid subdomain label — letters, digits and hyphens only." };
  const fqdn = `${clean}.${a.primaryDomain}`;
  if (!isValidHostingDomain(fqdn)) return { error: "That subdomain isn’t a valid hostname." };
  // Reject if another tenant already claimed this exact hostname as an addon domain
  // (or primary). fqdn @unique blocks subdomain↔subdomain; this closes the addon
  // path (audit HIGH-1, reverse direction).
  if (await isHostnameClaimed(fqdn)) {
    return { error: "That hostname is already in use on Nxeon." };
  }
  const { docroot } = subdomainPaths(a.username, clean);
  try {
    await db.$transaction(async (tx) => {
      const subs = await tx.hostingSubdomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
      const addons = await tx.hostingAddonDomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
      if (subs + addons >= a.maxSites) throw new Error("CAP");
      const sub = await tx.hostingSubdomain.create({ data: { accountId: a.id, label: clean, fqdn, docroot, status: "PENDING" } });
      // Atomic cross-tenant claim in the SAME tx: the UNIQUE(hostname) — not the
      // advisory isHostnameClaimed read above — is what actually stops a co-tenant
      // from committing this same server_name as their primary/subdomain/addon.
      await tx.hostingHostnameClaim.create({ data: { hostname: normalizeClaimHostname(fqdn), accountId: a.id, kind: "SUBDOMAIN" } });
      await tx.hostingTask.create({ data: { accountId: a.id, kind: "CREATE_SUBDOMAIN", payload: JSON.stringify({ subdomainId: sub.id }) } });
    }, { isolationLevel: "Serializable" });
  } catch (e) {
    if (e instanceof Error && e.message === "CAP") return { error: siteCapMessage(a.maxSites) };
    if (isUniqueViolation(e)) return { error: "That hostname is already in use on Nxeon." };
    return { error: "That subdomain already exists, or the request raced — try again." };
  }
  revalidatePath(`/dashboard/hosting/${accountId}`);
  return { ok: true };
}

export async function deleteSubdomain(id: string): Promise<HostingResult> {
  const user = await requireUser();
  const sub = await db.hostingSubdomain.findUnique({ where: { id }, include: { account: { select: { id: true, userId: true } } } });
  if (!sub) return { error: "Subdomain not found." };
  if (sub.account.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  await db.hostingSubdomain.update({ where: { id }, data: { status: "DELETING" } });
  await db.hostingTask.create({ data: { accountId: sub.account.id, kind: "DELETE_SUBDOMAIN", payload: JSON.stringify({ subdomainId: id }) } });
  revalidatePath(`/dashboard/hosting/${sub.account.id}`);
  return { ok: true };
}

export async function createAddonDomain(accountId: string, domain: string): Promise<HostingResult> {
  const ctx = await ownedSiteAccount(accountId);
  if ("error" in ctx) return { error: ctx.error };
  const { a } = ctx;
  const name = normalizeHostingDomain(domain);
  if (!name || !isValidHostingDomain(name)) return { error: "Enter a valid domain (e.g. example.com)." };
  if (name === a.primaryDomain) return { error: "That’s already your primary domain." };
  // Cross-tenant uniqueness across ALL three hostname tables — a shared vhost keys
  // on server_name, so an addon must not shadow anyone's primary, subdomain, or
  // addon (audit HIGH-1: this used to omit HostingSubdomain.fqdn).
  if (await isHostnameClaimed(name)) {
    return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
  }
  const { docroot } = addonDomainPaths(a.username, name);
  try {
    await db.$transaction(async (tx) => {
      const subs = await tx.hostingSubdomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
      const addons = await tx.hostingAddonDomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
      if (subs + addons >= a.maxSites) throw new Error("CAP");
      const addon = await tx.hostingAddonDomain.create({ data: { accountId: a.id, domain: name, docroot, status: "PENDING" } });
      // Atomic cross-tenant claim in the SAME tx: the UNIQUE(hostname) is the
      // authoritative guard against another tenant committing this same
      // server_name as their primary/subdomain/addon between our check and commit.
      await tx.hostingHostnameClaim.create({ data: { hostname: normalizeClaimHostname(name), accountId: a.id, kind: "ADDON" } });
      await tx.hostingTask.create({ data: { accountId: a.id, kind: "CREATE_ADDON_DOMAIN", payload: JSON.stringify({ addonId: addon.id }) } });
    }, { isolationLevel: "Serializable" });
  } catch (e) {
    if (e instanceof Error && e.message === "CAP") return { error: siteCapMessage(a.maxSites) };
    if (isUniqueViolation(e)) return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
    return { error: "That domain is already added, or the request raced — try again." };
  }
  revalidatePath(`/dashboard/hosting/${accountId}`);
  return { ok: true };
}

export async function deleteAddonDomain(id: string): Promise<HostingResult> {
  const user = await requireUser();
  const addon = await db.hostingAddonDomain.findUnique({ where: { id }, include: { account: { select: { id: true, userId: true } } } });
  if (!addon) return { error: "Domain not found." };
  if (addon.account.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  await db.hostingAddonDomain.update({ where: { id }, data: { status: "DELETING" } });
  await db.hostingTask.create({ data: { accountId: addon.account.id, kind: "DELETE_ADDON_DOMAIN", payload: JSON.stringify({ addonId: id }) } });
  revalidatePath(`/dashboard/hosting/${addon.account.id}`);
  return { ok: true };
}

