export type HostingWebsiteView = {
  /** Stable key: "primary" | "subdomain:<id>" | "addon:<id>". */
  key: string;
  kind: "primary" | "subdomain" | "addon";
  /** Row id for a subdomain/addon; null for the primary site. */
  id: string | null;
  hostname: string;
  /** Chroot-relative docroot for the file manager (e.g. `subdomains/shop/public_html`). */
  fileManagerPath: string;
  sslActive: boolean;
  status: string;

model HostingPlan {
  id            String           @id @default(cuid())
  slug          String           @unique
  name          String
  priceCents    Int
  diskGB        Int              @default(10)
  maxSites      Int              @default(1) // addon domains this account may host
  maxDatabases  Int              @default(1)
  bandwidthTB   Float            @default(1)
  // Bundled email mailboxes included with the plan. -1 = unlimited. Provisioned
  // on our own Nxeon Mail (Mailcow) backend when the account is created.
  mailboxes     Int              @default(1)
  // Marketing flags surfaced on the plan cards.
  freeMigration Boolean          @default(false) // "we move your existing site free"
  featured      Boolean          @default(false) // "Most popular" highlight
  tagline       String           @default("")     // one-line pitch under the plan name
  phpVersions   String           @default("8.3") // comma-separated allowed PHP versions
  active        Boolean          @default(true)
  sortOrder     Int              @default(0)
  createdAt     DateTime         @default(now())
  accounts      HostingAccount[]
}

enum HostingAccountStatus {
  PENDING // created, waiting for the provisioner
  PROVISIONING
  ACTIVE
  SUSPENDED
  FAILED
  DELETING
}

/// One customer's isolated shared-hosting account on a HostingNode: a jailed
/// Linux user with its own PHP-FPM pool, disk quota, primary domain and (later)
/// additional sites / databases / mailboxes. The unit of isolation and billing.
model HostingAccount {
  id            String               @id @default(cuid())
  userId        String
  user          User                 @relation(fields: [userId], references: [id], onDelete: Cascade)
  hostingNodeId String
  node          HostingNode          @relation(fields: [hostingNodeId], references: [id])
  planId        String
  plan          HostingPlan          @relation(fields: [planId], references: [id])
  // The jailed system username on the box (derived, unique per node). All the
  // account's files live under /home/<username>; its FPM pool runs AS this user.
  username      String
  primaryDomain String // the account's main domain (name-based vhost server_name)
  status        HostingAccountStatus @default(PENDING)
  // Effective quota snapshot (copied from the plan at creation so a plan edit
  // doesn't silently re-quota live accounts). ALWAYS already includes any purchased
  // `extraDiskGB` — it is (plan.diskGB + extraDiskGB) × 1024 — so the node's setquota
  // (taskApplyPlanLimits) never has to know about the add-on.
  diskQuotaMB   Int
  /// Purchased extra storage in GB, on TOP of the plan allowance (upsell). Add-only,
  /// mirroring Server.extraDiskGB — a live filesystem quota is only ever raised, never
  /// shrunk. Priced per-GB/month via `extra_disk_gb_price_cents` (the SAME rate VPS
  /// extra disk uses) and billed every renewal alongside the plan.
  extraDiskGB   Int                  @default(0)
  maxSites      Int
  maxDatabases  Int
  /// Billing term this account was SOLD on, in months: 1 = monthly, 12 = annual.
  /// The renewal sweep (worker/product-renewals.ts) charges
  /// `termPriceCents(plan.priceCents, termMonths, annualDiscountPct)` and pushes
  /// `expiresAt` forward this many months, so an annual account renews annually at
  /// the rate it was sold — displayed === charged === renewed. Defaults to 1 so
  /// every pre-existing row keeps billing monthly exactly as before.
  termMonths    Int                  @default(1)
  /// PERCENT the ANNUAL discount was set to when THIS account's term was sold — a
  /// snapshot of `annual_discount_percent` frozen at sale, exactly like
  /// Server.annualDiscountPct. The renewal reads THIS (falling back to the live
  /// setting when null) so an annual account renews at the sold rate even if the
  /// admin retunes the discount afterwards. NULL on monthly accounts and on rows
  /// that predate this column — the live setting is used for those, which for a
  /// monthly term changes nothing.
  annualDiscountPct Float?
  // PHP version the account's FPM pool runs (within the plan's allowed set).
  phpVersion    String               @default("8.3")
  // HTTPS: set once a per-domain Let's Encrypt cert is issued (SNI on the shared
  // IP). The SSL sweep flips this after the domain resolves to us.
  sslActive     Boolean              @default(false)
  // Live disk/inode usage, refreshed by hostingUsageSweep (null until first
  // measured). Powers the real usage meters in the customer panel.
  diskUsedMB    Int?
  inodesUsed    Int?
  usageAt       DateTime?
  // Serve-verification health, refreshed by hostingHealthSweep (null until first
  // checked). serveHttpOk/serveHttpsOk record whether nginx actually answers on
  // 80/443 for this domain from the node — the guardrail against a customer ever
  // seeing ERR_CONNECTION_REFUSED while the panel claims "active". healthNote is a
  // short human string for the DNS→HTTPS stepper; healthCheckedAt timestamps it.
  // recheckRequested is set by the customer "Check now / Go live" button so the
  // sweep picks that account up before its normal cadence, then clears it.
  serveHttpOk      Boolean?
  serveHttpsOk     Boolean?
  healthNote       String?
  healthCheckedAt  DateTime?
  recheckRequested Boolean   @default(false)
  // The account's SFTP/login password, encrypted; set at provision and shown to
  // the customer ONCE, then cleared. (SFTP is a reviewed later phase.)
  sftpPasswordEnc String?
  // The per-account, hard-to-guess URL path where the Adminer DB manager is
  // dropped inside this account's own webroot (e.g. /nxtools-<random>/adminer.php),
  // served by this account's own PHP-FPM socket. Null until the customer installs
  // it from the Databases tab. A leaked path yields no cross-tenant access: the
  // customer must still log in with their OWN scoped DB user (localhost, granted on
  // their databases only). See INSTALL_DBTOOL in worker/hosting.ts.
  dbToolPath      String?
  // Proprietary in-portal DB manager (Nxeon-built, replaces Adminer). A single
  // account-level MySQL user granted on `<username>\_%`.* ONLY — i.e. every one of
  // this account's databases and NOTHING else (db-scoped grant, so no global
  // FILE/PROCESS/SUPER either). Its password is encrypted AT REST (persistent,
  // like sftpPasswordEnc) because the manager re-authenticates as this user on
  // every query, server-side — the credential is NEVER sent to the browser. The
  // ENSURE_DBMGR task creates the user on the node; dbMgrReady flips true when it
  // succeeds. See lib/hosting-db.ts + lib/actions-hosting-db.ts.
  dbMgrUser       String?
  dbMgrPassEnc    String?
  dbMgrReady      Boolean @default(false)
  // Provisioning bookkeeping.
  error         String?
  provisionedAt DateTime?
  expiresAt     DateTime?
  suspendedNote String?
  createdAt     DateTime             @default(now())
  updatedAt     DateTime             @updatedAt
  databases     HostingDatabase[]
  tasks         HostingTask[]
  backups       HostingBackup[]
  subdomains    HostingSubdomain[]
  addonDomains  HostingAddonDomain[]
  crons         HostingCron[]
  hostnameClaims HostingHostnameClaim[]

  @@unique([hostingNodeId, username])
  @@index([userId])
  @@index([status])
}

/// Which kind of resource a hostname claim reserves. Purely descriptive — the
/// authoritative guarantee is the UNIQUE(hostname) on the claim row itself.
enum HostingClaimKind {
  PRIMARY
  SUBDOMAIN
  ADDON
}

/// Single authoritative registry of every hostname served on the fleet, spanning
/// ALL THREE places a name can live — an account's primary domain, a subdomain,
/// or an addon domain. The UNIQUE(hostname) is the atomic cross-tenant guard: a
/// claim row is inserted in the SAME transaction as the resource row it names, so
/// two concurrent requests that both pass the advisory isHostnameClaimed()
/// pre-check can never both commit the same nginx `server_name` — the second
/// INSERT fails on the unique (Prisma P2002) and rolls its whole transaction back.
/// Before this table there was no single constraint spanning the three hostname
/// tables (primaryDomain has no unique), so co-tenants on one node could shadow
/// each other's vhost (security audit: co-tenant vhost-shadowing TOCTOU). The
/// hostname is stored normalized (trimmed + lowercased) so case/format variants
/// can't dodge the unique. Freed by deleting the row when the resource is removed
/// (same tx as the delete / on account termination); the accountId relation also
/// cascades if the account row is ever hard-deleted.
model HostingHostnameClaim {
  id        String           @id @default(cuid())
  hostname  String           @unique
  accountId String
  account   HostingAccount   @relation(fields: [accountId], references: [id], onDelete: Cascade)
  kind      HostingClaimKind
  createdAt DateTime         @default(now())

  @@index([accountId])
}

enum HostingTaskKind {
  PHP_SWITCH
  WORDPRESS_INSTALL
  APP_INSTALL
  BACKUP
  RESTORE
  // Account lifecycle — enacted by the provisioner (inert until ENABLE_SHARED_HOSTING).
  SUSPEND // disable vhost + FPM pool + lock the unix user (reversible)
  UNSUSPEND // reverse a SUSPEND
  TERMINATE // remove vhost/FPM, delete the jailed user + home, drop scoped DBs
  // cPanel-class site management — each queues one node operation (inert until enabled).
  CREATE_SUBDOMAIN // mkdir a docroot + write/enable a <label>.<primary> vhost
  DELETE_SUBDOMAIN // reverse: remove the vhost + docroot
  CREATE_ADDON_DOMAIN // full external domain: own docroot + vhost
  DELETE_ADDON_DOMAIN // reverse: remove the vhost + docroot
  CREATE_CRON // (re)write the jailed user's crontab from its ACTIVE cron rows
  DELETE_CRON // remove a cron row + rewrite the crontab
  // Drop the Adminer DB manager into the account webroot (served by the account's
  // own FPM socket; login is the customer's scoped DB user — no root, no auto-login).
  INSTALL_DBTOOL
  // Create/repair the account-level scoped MySQL user for the proprietary in-portal
  // DB manager (granted on `<username>\_%`.* only). Idempotent. See taskEnsureDbMgr.
  ENSURE_DBMGR
  // Re-apply the account's snapshotted plan limits on the node after a plan upgrade
  // (raise the disk quota via setquota; rewrite the FPM pool). Idempotent.
  APPLY_PLAN_LIMITS
  // Change a scoped MySQL user's password on the node (customer-initiated DB
  // password reset). Runs ALTER USER … IDENTIFIED BY. Idempotent. See taskResetDbPassword.
  RESET_DB_PASSWORD
  // Promote a real domain (an existing ACTIVE addon domain) to the account's
  // primaryDomain: regenerate the primary vhost hosting-<user>.conf with the new
  // domain as server_name, KEEP the old primary hostname as an alias server_name
  // (so the old address keeps working), run `wp search-replace`+`option update`
  // when WordPress is detected in the primary docroot, then flip DB primaryDomain
  // and re-key the hostname claims. Worst-case safe: on any failure the old
  // address keeps serving and primaryDomain is left unchanged. See taskSetPrimaryDomain.
  SET_PRIMARY_DOMAIN
}

enum HostingTaskStatus {
  PENDING
  RUNNING
  DONE
  FAILED
}

/// A queued panel operation on an account, run by the worker over the node SSH
/// (PHP switch, one-click app install, backup, restore). `payload`/`result` hold
/// small JSON; any secret in a result (e.g. a WordPress admin password) is
/// shown ONCE then cleared.
model HostingTask {
  id        String            @id @default(cuid())
  accountId String
  account   HostingAccount    @relation(fields: [accountId], references: [id], onDelete: Cascade)
  kind      HostingTaskKind
  status    HostingTaskStatus @default(PENDING)
  payload   String? // JSON in
  result    String? // JSON out (may hold a one-time secret until read)
  error     String?
  createdAt DateTime          @default(now())
  updatedAt DateTime          @updatedAt

  @@index([status])
  @@index([accountId])
}

/// A stored backup of an account (home archive + DB dumps) on its node.
model HostingBackup {
  id        String         @id @default(cuid())
  accountId String
  account   HostingAccount @relation(fields: [accountId], references: [id], onDelete: Cascade)
  path      String // absolute path of the archive on the node
  sizeBytes Int            @default(0)
  createdAt DateTime       @default(now())

  @@index([accountId])
}

enum HostingDatabaseStatus {
  PENDING
  ACTIVE
  FAILED
  DELETING
}

/// A MySQL/MariaDB database + its scoped owner user for a hosting account. The
/// generated password is shown ONCE at creation; `passwordEnc` holds it only
/// transiently so the provisioner can apply it, then it is cleared. The DB user
/// is granted rights on THIS database only — the shared-box isolation boundary
/// for data.

async function taskApplyPlanLimits(conn: Client, a: { id: string; username: string; phpVersion: string; diskQuotaMB: number }): Promise<void> {
  const u = a.username;
  if (!isValidUnixUsername(u)) throw new Error("unsafe account username");
  if (!/^\d\.\d$/.test(a.phpVersion)) throw new Error("unsafe php version");
  const { home, webroot } = accountPaths(u);
  const hardBlocks = diskQuotaBlocks(Math.max(1, Math.round(a.diskQuotaMB / 1024)));
  const softBlocks = Math.floor(hardBlocks * 0.95);
  await run(conn, "raise disk quota", `command -v setquota >/dev/null 2>&1 && setquota -u ${u} ${softBlocks} ${hardBlocks} 0 0 /home || echo 'quota tool absent — skipped'`);
  await writeFpmPool(conn, u, home, webroot, a.phpVersion);
}

/**
 * Promote an ACTIVE addon domain to the account's PRIMARY domain.
 *
 * The account's MAIN website (its `public_html`, reached until now at the old
 * primary address) starts answering on the new domain, and the OLD primary is kept
 * as an ALIAS server_name so its address keeps working. Order is chosen so the old
 * address NEVER stops serving:
 *   1. Regenerate the primary vhost `hosting-<user>.conf` with the new domain as
 *      server_name + the old domain as an alias (nginx -t guarded). We pick a cert
 *      dir that is GUARANTEED to exist — the real Let's Encrypt cert for the new
 *      domain if the addon already had one, else the account's self-signed fallback
 *      — so `nginx -t` can't fail on a missing cert and 443 keeps listening.
 *   2. Remove the addon's OWN vhost (it now conflicts with the primary's
 *      server_name). The addon docroot files are LEFT on disk (data retention).
 *   3. If WordPress lives in the primary docroot, rewrite its stored URLs.
 * Only after every node step succeeds do we flip DB `primaryDomain`, delete the
 * addon row and re-key the hostname claim (new → PRIMARY; old stays claimed as the
 * alias). On any failure we throw BEFORE the DB flip, so the account keeps its old
 * primary domain and — because the primary vhost already carries the old name as an
 * alias — the old address keeps serving. `sslActive` is reset unless a real cert for
 * the new domain is already live, so the SSL sweep issues/verifies one.
 */
async function taskSetPrimaryDomain(
  conn: Client,
  a: { id: string; username: string; primaryDomain: string },
  payload: string | null,
): Promise<string> {
  const addonId = String(JSON.parse(payload || "{}").addonId ?? "");
  const addon = await db.hostingAddonDomain.findFirst({ where: { id: addonId, accountId: a.id } });
  if (!addon) throw new Error("addon domain not found");
  if (addon.status !== "ACTIVE") throw new Error("the domain is still being set up");
  const u = a.username;
  const newDomain = addon.domain;
  const oldDomain = a.primaryDomain;
  if (!isValidUnixUsername(u)) throw new Error("unsafe account username");
  if (!isValidHostingDomain(newDomain)) throw new Error("unsafe new primary domain");
  if (!isValidHostingDomain(oldDomain)) throw new Error("unsafe old primary domain");
  if (newDomain === oldDomain) {
    // Already the primary (defensive) — just clean up the addon bookkeeping.
    await db.hostingAddonDomain.delete({ where: { id: addon.id } }).catch(() => undefined);
    return JSON.stringify({ note: `${newDomain} is already your primary domain.` });
  }
  const { webroot } = accountPaths(u);
  const sock = `/run/php/${u}.sock`;

  // Pick a cert dir that DEFINITELY exists so `nginx -t` can never fail on it.
  const realLive = `/etc/letsencrypt/live/${newDomain}`;
  const haveReal = (await exec(conn, `test -s ${realLive}/fullchain.pem && echo yes || echo no`)).out.trim() === "yes";
  const certDir = haveReal ? realLive : selfSignedCertDir(u);

  // 1. Repoint the primary vhost: new domain as server_name, old kept as an alias.
  await installVhost(conn, u, renderHostingVhost(u, newDomain, webroot, sock, { certDir, real: haveReal }, [oldDomain]));
  // 2. Drop the addon's own vhost (its server_name now belongs to the primary). Keep
  //    its docroot files on disk.
  await removeNamedVhost(conn, `${u}-${newDomain}`);
  // 3. WordPress URL rewrite, when the PRIMARY docroot actually runs WordPress.
  const isWp = (await exec(conn, `sudo -u ${u} -H wp --path=${webroot} core is-installed >/dev/null 2>&1 && echo yes || echo no`)).out.trim() === "yes";
  if (isWp) {
    const wp = `sudo -u ${u} -H wp --path=${webroot}`;
    await run(conn, "wp search-replace", `${wp} search-replace '${oldDomain}' '${newDomain}' --all-tables --skip-columns=guid`);
    await run(conn, "wp home/siteurl", `${wp} option update home 'https://${newDomain}' && ${wp} option update siteurl 'https://${newDomain}'`);
  }

  // Node is consistent — commit the DB flip. Re-key the hostname claim (new domain
  // ADDON → PRIMARY); the old domain keeps its existing claim as the served alias.
  await db.hostingAccount.update({
    where: { id: a.id },
    data: { primaryDomain: newDomain, sslActive: haveReal, recheckRequested: true },
  });
  await db.hostingHostnameClaim
    .updateMany({ where: { hostname: normalizeClaimHostname(newDomain) }, data: { kind: "PRIMARY" } })
    .catch(() => undefined);
  await db.hostingAddonDomain.delete({ where: { id: addon.id } }).catch(() => undefined);
  return JSON.stringify({ note: `Primary domain is now ${newDomain}. ${oldDomain} still works.`, url: `https://${newDomain}/` });
}

async function processHostingTask(taskId: string): Promise<void> {
  const task = await db.hostingTask.findUnique({ where: { id: taskId }, include: { account: { include: { node: true } } } });
  if (!task || task.status !== "PENDING") return;
  await db.hostingTask.update({ where: { id: task.id }, data: { status: "RUNNING" } });
  const a = task.account;
  // Lifecycle tasks deliberately run on a NON-active account: the admin action
  // flips status to SUSPENDED / DELETING *before* queuing, so gating them on ACTIVE
  // (like the content tasks) would make suspend/terminate silent no-ops — the kill
  // switch must still fire. Content tasks (PHP/WP/backup/restore) stay ACTIVE-only.
  const isLifecycle = task.kind === "SUSPEND" || task.kind === "UNSUSPEND" || task.kind === "TERMINATE";
  if (!isLifecycle && a.status !== "ACTIVE") { await failTask(task.id, "the account is not active"); return; }
  try {
    const conn = await connectNode(a.node);
    try {
      let result: string | null = null;
      if (task.kind === "PHP_SWITCH") await taskPhpSwitch(conn, a, task.payload);
      else if (task.kind === "WORDPRESS_INSTALL") result = await taskWordpressInstall(conn, a, task.payload);
      else if (task.kind === "APP_INSTALL") result = await taskAppInstall(conn, a, task.payload);
      else if (task.kind === "BACKUP") await taskBackup(conn, a, task.id);
      else if (task.kind === "RESTORE") await taskRestore(conn, a, task.payload);
      else if (task.kind === "SUSPEND") await taskSuspend(conn, a);
      else if (task.kind === "UNSUSPEND") await taskUnsuspend(conn, a);
      else if (task.kind === "TERMINATE") await taskTerminate(conn, a);
      else if (task.kind === "CREATE_SUBDOMAIN") await taskCreateSubdomain(conn, a, task.payload);
      else if (task.kind === "DELETE_SUBDOMAIN") await taskDeleteSubdomain(conn, a, task.payload);
      else if (task.kind === "CREATE_ADDON_DOMAIN") await taskCreateAddonDomain(conn, a, task.payload);
      else if (task.kind === "DELETE_ADDON_DOMAIN") await taskDeleteAddonDomain(conn, a, task.payload);
      else if (task.kind === "CREATE_CRON") await taskCreateCron(conn, a, task.payload);
      else if (task.kind === "DELETE_CRON") await taskDeleteCron(conn, a, task.payload);
      else if (task.kind === "INSTALL_DBTOOL") result = await taskInstallDbTool(conn, a, task.payload);
      else if (task.kind === "ENSURE_DBMGR") await taskEnsureDbMgr(conn, a);
      else if (task.kind === "APPLY_PLAN_LIMITS") await taskApplyPlanLimits(conn, a);
      // Cast: the symlinked prod Prisma client's HostingTaskKind predates this new
      // value until it is regenerated at deploy (same as HostingAccount.termMonths).
      else if ((task.kind as string) === "RESET_DB_PASSWORD") await taskResetDbPassword(conn, a, task.payload);
      else if ((task.kind as string) === "SET_PRIMARY_DOMAIN") result = await taskSetPrimaryDomain(conn, a, task.payload);
      await db.hostingTask.update({ where: { id: task.id }, data: { status: "DONE", result, error: null } });
      // FINALIZE a termination. taskTerminate deprovisions the node (vhost, FPM, DBs,
      // jailed user, hostname claims) but the account row itself lived on in DELETING
      // forever — nothing removed it — so the admin list showed accounts stuck
      // "deleting" indefinitely. Now that the node is clean, delete the row; every
      // child (tasks incl. this one, databases, subdomains, addons, crons, backups)
      // is onDelete:Cascade, so the account and its history drop in one statement and
      // it disappears from the panel. Financial history rides the user/wallet, not the
      // account, so nothing billable is lost.
      if (task.kind === "TERMINATE") {
        await db.hostingAccount.delete({ where: { id: a.id } }).catch(async () => {
          // Extremely unlikely (all FKs cascade); if it ever fails, at least don't
          // leave it wedged in DELETING — surface it as FAILED so an operator sees it.
          await db.hostingAccount.update({ where: { id: a.id }, data: { status: "FAILED" } }).catch(() => {});
        });
      }
    } finally { try { conn.end(); } catch { /* */ } }
  } catch (e) {
    await failTask(task.id, (e instanceof Error ? e.message : String(e)).slice(0, 300));
  }
}

export async function hostingTaskSweep(): Promise<void> {
  if (SANDBOX) {
    const pend = await db.hostingTask.findMany({ where: { status: "PENDING" }, select: { id: true, kind: true, payload: true, accountId: true, account: { select: { primaryDomain: true } } }, take: 10 });
    for (const t of pend) {
      // Apply the resource side-effects so the panel reflects the change in dev.
      const p = (() => { try { return JSON.parse(t.payload || "{}"); } catch { return {}; } })() as { subdomainId?: string; addonId?: string; cronId?: string; path?: string; target?: { kind?: string; id?: string } };
      // Resolve an install task's TARGET hostname (primary by default, else the
      // subdomain/addon it was aimed at) so the one-time result URL is site-correct.
      let installHost = t.account.primaryDomain;
      if ((t.kind === "WORDPRESS_INSTALL" || t.kind === "APP_INSTALL") && p.target?.id) {
        if (p.target.kind === "subdomain") {
          const sub = await db.hostingSubdomain.findFirst({ where: { id: p.target.id, accountId: t.accountId }, select: { fqdn: true } }).catch(() => null);
          if (sub) installHost = sub.fqdn;
        } else if (p.target.kind === "addon") {
          const ad = await db.hostingAddonDomain.findFirst({ where: { id: p.target.id, accountId: t.accountId }, select: { domain: true } }).catch(() => null);
          if (ad) installHost = ad.domain;
        }
      }
      let result = t.kind === "WORDPRESS_INSTALL" ? JSON.stringify({ app: "WordPress", adminUser: "admin", adminPassword: "sandbox-demo-pw", url: `https://${installHost}/wp-admin/` })
        : t.kind === "APP_INSTALL" ? JSON.stringify({ app: "App", url: `https://${installHost}/`, note: "Sandbox: finish the installer in your browser." }) : null;
      // Set-primary: flip primaryDomain, delete the addon, re-key the claim — so the
      // Websites panel + Overview reflect the promotion without a real box.
      if ((t.kind as string) === "SET_PRIMARY_DOMAIN" && p.addonId) {
        const ad = await db.hostingAddonDomain.findFirst({ where: { id: p.addonId, accountId: t.accountId }, select: { domain: true } }).catch(() => null);
        if (ad) {
          await db.hostingAccount.update({ where: { id: t.accountId }, data: { primaryDomain: ad.domain, sslActive: false, recheckRequested: true } }).catch(() => undefined);
          await db.hostingHostnameClaim.updateMany({ where: { hostname: normalizeClaimHostname(ad.domain) }, data: { kind: "PRIMARY" } }).catch(() => undefined);
          await db.hostingAddonDomain.delete({ where: { id: p.addonId } }).catch(() => undefined);
          result = JSON.stringify({ note: `Primary domain is now ${ad.domain}.`, url: `https://${ad.domain}/` });
        }
      }
      if (t.kind === "INSTALL_DBTOOL" && p.path) await db.hostingAccount.update({ where: { id: t.accountId }, data: { dbToolPath: p.path } }).catch(() => undefined);
      if (t.kind === "ENSURE_DBMGR") await db.hostingAccount.update({ where: { id: t.accountId }, data: { dbMgrReady: true } }).catch(() => undefined);
      if (t.kind === "CREATE_SUBDOMAIN" && p.subdomainId) await db.hostingSubdomain.update({ where: { id: p.subdomainId }, data: { status: "ACTIVE" } }).catch(() => undefined);
      else if (t.kind === "DELETE_SUBDOMAIN" && p.subdomainId) {
        const gone = await db.hostingSubdomain.findUnique({ where: { id: p.subdomainId }, select: { fqdn: true } }).catch(() => null);
        await db.hostingSubdomain.delete({ where: { id: p.subdomainId } }).catch(() => undefined);
        if (gone) await db.hostingHostnameClaim.deleteMany({ where: { hostname: normalizeClaimHostname(gone.fqdn) } }).catch(() => undefined);
      }
      else if (t.kind === "CREATE_ADDON_DOMAIN" && p.addonId) await db.hostingAddonDomain.update({ where: { id: p.addonId }, data: { status: "ACTIVE" } }).catch(() => undefined);
      else if (t.kind === "DELETE_ADDON_DOMAIN" && p.addonId) {
        const gone = await db.hostingAddonDomain.findUnique({ where: { id: p.addonId }, select: { domain: true } }).catch(() => null);
        await db.hostingAddonDomain.delete({ where: { id: p.addonId } }).catch(() => undefined);
        if (gone) await db.hostingHostnameClaim.deleteMany({ where: { hostname: normalizeClaimHostname(gone.domain) } }).catch(() => undefined);
      }
      else if (t.kind === "CREATE_CRON" && p.cronId) await db.hostingCron.update({ where: { id: p.cronId }, data: { status: "ACTIVE" } }).catch(() => undefined);
      else if (t.kind === "DELETE_CRON" && p.cronId) await db.hostingCron.delete({ where: { id: p.cronId } }).catch(() => undefined);
      await db.hostingTask.update({ where: { id: t.id }, data: { status: "DONE", result } });
      if (t.kind === "BACKUP") await db.hostingBackup.create({ data: { accountId: t.accountId, path: `/var/hosting-backups/sandbox/${t.id}.tar.gz`, sizeBytes: 12_345_678 } }).catch(() => undefined);
    }
    return;
  }
  if (!ENABLED) return;
  const pend = await db.hostingTask.findMany({ where: { status: "PENDING" }, select: { id: true }, take: 5 });
  for (const t of pend) await processHostingTask(t.id).catch((e) => console.error(`[hosting] task ${t.id} failed`, e));
}

