// Shared server-upgrade (RESIZE up) core — used by the wallet flow
// (lib/actions-server.ts resizeServer) and by the Stripe confirm route so a paid
// checkout can apply the upgrade immediately. Plain server module (not "use server").
import { db } from "./db";
import { debitWallet, InsufficientBalanceError } from "./wallet";
import { invoiceCreateData } from "./invoices";
import { prorateUpgradeCents, remainingMonths } from "./proration";
import { annualDiscountPct, frozenAnnualDiscountPct } from "./annual-discount";

/**
 * Average calendar month in ms — RE-EXPORTED from lib/proration.ts, never
 * redeclared.
 *
 * It used to be its own `30.44 * 86400_000` here, a byte-identical twin of the one
 * in lib/proration.ts, and lib/disk-expand.ts imported THIS copy while every other
 * proration read the other. Two constants that happen to be equal are still two
 * constants: the day someone tunes one (to 365/12, or to a real calendar month) the
 * disk-expansion charge and the plan-resize charge quietly start pricing the same
 * remaining term differently. This file's whole history is second copies of a
 * number drifting, so there is one and it lives with the proration maths.
 */
export { MS_PER_AVG_MONTH } from "./proration";

export class ResizeError extends Error {}

type QuotedServer = Awaited<ReturnType<typeof loadServer>>;
type QuotedPlan = NonNullable<Awaited<ReturnType<typeof loadPlan>>>;

function loadServer(serverId: string) {
  return db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
}
function loadPlan(planId: string) {
  return db.plan.findUnique({ where: { id: planId } });
}

export type ResizeQuote = {
  server: NonNullable<QuotedServer>;
  newPlan: QuotedPlan;
  prorateCents: number;
};

/**
 * Validate an UPGRADE and compute the prorated charge over the ACTUAL remaining
 * duration (monthly price difference for every remaining month; null expiresAt
 * on free/admin servers => 0). Throws ResizeError with a user-facing message on
 * any guard failure. Does NOT check ownership — callers must do that.
 *
 * ─── INTERACTION WITH PER-SERVER EXTRA DISK ─────────────────────────────────
 * `Server.extraDiskGB` (disk bought via the deploy upsell or "Add storage") is
 * ADDITIVE to whichever plan the server is on, so a plan change must leave it
 * completely alone. Two things follow, and both are deliberate:
 *
 *  1. NOT DOUBLE-CHARGED. The proration below is a difference of PLAN monthly
 *     prices. The extra-disk surcharge is identical before and after the resize
 *     (same GB, same per-GB price), so it cancels out of the delta exactly — it
 *     must never be added here. It keeps being billed, unchanged, by the renewal
 *     sweep, which reads `extraDiskGB` directly.
 *  2. NOT LOST. Nothing in the resize path writes `extraDiskGB`, and the worker's
 *     RESIZE handler sizes the disk to `newPlan.diskGB + server.extraDiskGB` — so
 *     the customer keeps every GB they paid for. (Sizing to the bare plan disk
 *     would ask Proxmox to SHRINK the disk of any server holding extra storage,
 *     and the whole resize would hard-fail.)
 *
 * The disk-grow guard below intentionally compares PLAN disks, not effective
 * disks: since the extra is added to both sides, a target plan with an equal or
 * larger disk can never shrink the effective disk.
 */
export async function resizeQuote(serverId: string, planId: string): Promise<ResizeQuote> {
  const server = await loadServer(serverId);
  if (!server) throw new ResizeError("Not found");
  const newPlan = await loadPlan(planId);
  if (!newPlan?.active) throw new ResizeError("Plan not available.");
  if (newPlan.id === server.planId) throw new ResizeError("Server is already on this plan.");
  // A GAME server is not priced from `plan` at all, so it cannot be prorated
  // against it.
  //
  // Game tiers carry BOTH a base `planId` and a `gamePlanId`, and are sold at
  // `gamePlan.priceCents` — a FLAT, all-in price, typically LOWER than the base
  // plan they run on. The live row: `minecraft-mm8w85` sold at $4.99 on a Starter
  // base plan of $8.99. `renewalCharge` already treats a game plan as all-in with
  // no add-on lines; every proration path read `server.plan.priceCents` and was
  // blind to it.
  //
  // The dangerous direction is the CREDIT. lib/proration.ts rests on one
  // invariant — a prorated credit is strictly less than the cash actually
  // collected for those months — and that is the whole argument in
  // `resolveTermPromoPercent`. A tier sold at $9.99/mo flat on a $20.99 base plan
  // credits $20.99-worth per remaining month on a downgrade: real wallet money the
  // customer never paid, self-service.
  //
  // Today it is blocked only by the disk-monotonic guard below — in a catalogue
  // where price and disk both rise, no cheaper plan has equal-or-larger disk. That
  // is a coincidence of the current price list, not a protection; one cheap
  // high-disk plan opens it. lib/proration.ts's header calls out exactly this shape
  // about the pre-2026-07-25 bug, so it is refused explicitly rather than left
  // resting on an unrelated guard.
  if (server.gamePlanId) {
    throw new ResizeError(
      "Game server plans are fixed bundles — switch tiers from the game server's own settings, or contact support.",
    );
  }
  if (newPlan.diskGB < server.plan.diskGB) {
    throw new ResizeError("Disk storage can only grow — choose a plan with equal or larger disk.");
  }
  if (newPlan.priceCents < server.plan.priceCents) {
    throw new ResizeError("Downgrades aren't self-service yet — please contact support.");
  }
  if (!["RUNNING", "STOPPED"].includes(server.status)) throw new ResizeError("Server is busy.");

  let prorateCents = 0;
  if (!server.isFree && server.expiresAt) {
    // Price the upgrade at the term discount AND the rate THIS SERVER'S TERM WAS
    // SOLD AT (`server.termPromoPercent`, persisted at every point a term is
    // bought). Using the raw list-price delta (as this did until 2026-07-25)
    // overcharged by the whole discount stack: on a 36-month term with a 30% promo
    // running, $1,044.45 to upgrade versus $665.08 to simply buy the same plan
    // outright for the same end date. Pricing off `currentPromo(now)` instead (as
    // it did until 2026-07-26) was worse: the customer picked the rate by picking
    // the date, upgrading under Cyber Monday's 45% and downgrading under the 15%
    // Launch Sale to pocket the spread. Shared with the downgrade credit and with
    // the client picker via lib/proration.ts so displayed, charged and credited
    // cannot drift apart.
    //
    // `remainingMonths` covers EVERY month left on `expiresAt` and takes no cap —
    // see the note on it. Charging the full stacked duration here is what makes the
    // mirror-image downgrade credit safe to pay out over the same duration: after
    // this charge the customer has genuinely paid the new plan's rate for every one
    // of those months. Capping this side alone would mint money on a round trip;
    // capping the credit side alone destroyed $362.88 of it until 2026-07-26.
    prorateCents = prorateUpgradeCents({
      fromMonthlyCents: server.plan.priceCents,
      toMonthlyCents: newPlan.priceCents,
      termMonths: server.termMonths,
      termPromoPercent: server.termPromoPercent,
      // The annual rate this server was SOLD at (frozen at order), falling back to the
      // LIVE setting only for legacy rows that predate the snapshot — so an admin retuning
      // `annual_discount_percent` between an upgrade and a later downgrade can't break the
      // round-trip-to-zero invariant (Finding 2). The downgrade credit reads the same value.
      annualDiscountPct: frozenAnnualDiscountPct(server) ?? (await annualDiscountPct()),
      monthsRemaining: remainingMonths(server.expiresAt, Date.now()),
    });
  }
  return { server, newPlan, prorateCents };
}

/**
 * Apply the upgrade: (optionally) debit the wallet for the prorated charge, record
 * the wallet transaction + PAID invoice, and queue the RESIZE job that the worker
 * performs on Proxmox. Re-validates every guard (plan availability, disk-grow,
 * not a downgrade, steady state, one in-flight job) so it is safe to call from the
 * unauthenticated confirm route. Throws ResizeError on any guard failure.
 *
 * `chargeCents` overrides the recomputed proration — the paid path passes the exact
 * amount the customer paid into their wallet at checkout so the debit here nets to
 * zero against that credit (mirrors how the deploy confirm re-runs placeOrder to
 * spend the just-credited funds). The wallet path omits it and debits the quote.
 */
export async function applyResize(opts: {
  serverId: string;
  planId: string;
  actorUserId: string;
  chargeCents?: number;
}): Promise<void> {
  const { server, newPlan, prorateCents: quoted } = await resizeQuote(opts.serverId, opts.planId);
  const prorateCents = opts.chargeCents ?? quoted;

  const pending = await db.job.count({ where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } } });
  if (pending > 0) throw new ResizeError("Another operation is already in progress on this server.");

  try {
    await db.$transaction(async (tx) => {
      if (prorateCents > 0) {
        await debitWallet(tx, server.userId, prorateCents);
        await tx.walletTransaction.create({
          data: {
            userId: server.userId,
            amountCents: -prorateCents,
            description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}`,
          },
        });
        // PAID invoice for the proration charge (one per user-initiated resize).
        await tx.invoice.create({
          data: invoiceCreateData({
            userId: server.userId,
            description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}`,
            status: "PAID",
            lineItems: [
              { description: `Upgrade to ${newPlan.name} — prorated for remaining term (${server.hostname})`, qty: 1, unitCents: prorateCents, amountCents: prorateCents },
            ],
          }),
        });
      }
      // NOTE: a plan change deliberately does NOT touch `termPromoPercent`. It does
      // not re-base the term — `expiresAt` is untouched and no new months are sold —
      // it only moves the customer to a different plan at the rate they already
      // bought. Keeping the scalar is exactly what makes upgrade-then-downgrade net
      // to zero: both halves read the same stored basis. (This is also why the basis
      // is stored as a percent rather than a $/mo figure: a cents rate would have to
      // be rewritten here, and that rewrite is one more place to get it wrong.)
      //
      // Record the amount charged on the job so the worker's RESIZE handler can
      // REVERSE it (credit `payload.prorateCents` back to the wallet) if the
      // resize terminally fails — money is committed here, before the job runs.
      await tx.job.create({
        data: { type: "RESIZE", serverId: server.id, payload: { planId: opts.planId, prorateCents, direction: "up" } as any },
      });
      await tx.auditLog.create({
        data: { userId: opts.actorUserId, action: "server.resize", detail: `${server.id} -> ${newPlan.slug} prorate=${prorateCents}` },
      });
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) throw new ResizeError("Insufficient balance — top up your wallet first.");
    throw e;
  }
}

