"use client";

import { useMemo } from "react";
import { loadStripe, type Stripe } from "@stripe/stripe-js";
import { EmbeddedCheckoutProvider, EmbeddedCheckout } from "@stripe/react-stripe-js";

/**
 * The ONE payment surface for the whole platform — Stripe Embedded Checkout rendered
 * in a modal ON our own page. Nobody is ever redirected to a Stripe-branded page: the
 * payment UI mounts inside this dialog (styled by our appearance settings), and on
 * completion Stripe navigates to the session's `return_url` — our own `/api/stripe/confirm`
 * route — which runs the SAME idempotent fulfilment the webhook does. So the audited
 * fulfilment engine is untouched; only the presentation changed from "redirect" to
 * "embedded modal".
 *
 * Usage: a flow's server action now returns `{ clientSecret, publishableKey }` (from a
 * Checkout Session created with `ui_mode: "embedded"`). The caller stores it in state and
 * renders `<StripeCheckoutModal ... onClose={...} />`.
 */

// loadStripe returns a singleton per key — cache so we don't re-init Stripe.js each open.
const stripeCache = new Map<string, Promise<Stripe | null>>();
function stripeFor(pk: string): Promise<Stripe | null> {
  let p = stripeCache.get(pk);
  if (!p) {
    p = loadStripe(pk);
    stripeCache.set(pk, p);
  }
  return p;
}

export function StripeCheckoutModal({
  clientSecret,
  publishableKey,
  onClose,
  title = "Checkout",
}: {
  clientSecret: string;
  publishableKey: string;
  onClose: () => void;
  title?: string;
}) {
  const stripePromise = useMemo(() => stripeFor(publishableKey), [publishableKey]);

  return (
    <div
      className="fixed inset-0 z-[100] flex items-start justify-center overflow-y-auto bg-black/60 p-4 backdrop-blur-sm sm:p-8"
      role="dialog"
      aria-modal="true"
      aria-label={title}
    >
      <div className="relative my-auto w-full max-w-xl rounded-2xl border border-white/10 bg-navy-950 p-2 shadow-2xl">
        <div className="flex items-center justify-between px-3 pb-1 pt-2">
          <span className="text-sm font-semibold text-slate-200">{title}</span>
          <button
            type="button"
            onClick={onClose}
            aria-label="Close checkout"
            className="rounded-lg px-2 py-1 text-slate-400 transition hover:bg-white/5 hover:text-white"
          >
            ✕
          </button>
        </div>
        {/* Embedded Checkout renders inside this container — no navigation to Stripe. */}
        <div className="rounded-xl bg-white p-1">
          <EmbeddedCheckoutProvider stripe={stripePromise} options={{ clientSecret }}>
            <EmbeddedCheckout />
          </EmbeddedCheckoutProvider>
        </div>
      </div>
    </div>
  );
}

