"use client";

import { useState, useTransition } from "react";
import { resizeServer } from "@/lib/actions-server";
import { StripeCheckoutModal } from "@/components/customer/StripeCheckoutModal";
import { fmtMoney } from "@/components/ui/primitives";
import { walletSplit, STRIPE_MIN_CENTS } from "@/lib/wallet-split";
import { prorateUpgradeCents, remainingMonths } from "@/lib/proration";

type PlanRow = {
  id: string;
  name: string;
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  bandwidthTB: number;
  priceCents: number;
};

export function ResizePicker({
  serverId,
  currentPlanId,
  currentDiskGB,
  currentPriceCents,
  extraDiskGB = 0,
  expiresAt,
  termMonths,
  termPromoPercent,
  annualDiscountPct,
  isFree,
  walletBalanceCents,
  plans,
  disabled,
}: {
  serverId: string;
  currentPlanId: string;
  currentDiskGB: number;
  currentPriceCents: number;
  /** The server's billing term — proration is priced at the term-discounted rate. */
  termMonths: number;
  /**
   * The admin ANNUAL discount (`annual_discount_percent`), passed from the server
   * page so a 12-month server's upgrade estimate here matches the rate lib/resize.ts
   * charges. Only affects annual servers; harmless on every other term.
   */
  annualDiscountPct: number;
  /**
   * `Server.termPromoPercent` — the rate the remaining months were actually sold
   * at. Passed down verbatim (null included) so this display and lib/resize.ts
   * resolve the SAME basis; showing a figure computed off today's promo while the
   * server charged the persisted rate is precisely the drift this file's tripwire
   * test exists to catch.
   */
  termPromoPercent: number | null;
  /**
   * GB of separately-purchased extra disk. Additive to whichever plan the server
   * is on, so it survives this resize untouched and is NOT part of the proration
   * (the plan-price delta cancels it out) — see lib/resize.ts resizeQuote.
   */
  extraDiskGB?: number;
  /** ISO string of the current term end, or null (free/admin servers). */
  expiresAt: string | null;
  isFree: boolean;
  walletBalanceCents: number;
  plans: PlanRow[];
  disabled?: boolean;
}) {
  const [selected, setSelected] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [checkout, setCheckout] = useState<{ clientSecret: string; publishableKey: string } | null>(null);
  const [pending, start] = useTransition();
  // Apply the wallet balance by default whenever there's something to apply.
  const [useWallet, setUseWallet] = useState(walletBalanceCents > 0);
  const target = plans.find((p) => p.id === selected);

  // Prorated upgrade charge. Calls the SAME shared function the server uses
  // (lib/proration.ts), not a reimplementation — the previous copy here and in
  // lib/resize.ts happened to agree, and both were wrong in the same way
  // (undiscounted list price, overcharging by up to $379 on a long term). One
  // function means displayed and charged cannot drift apart even when the pricing
  // rules change. The server still recomputes authoritatively.
  function estimateProrate(newPriceCents: number): number {
    if (isFree || !expiresAt) return 0;
    return prorateUpgradeCents({
      fromMonthlyCents: currentPriceCents,
      toMonthlyCents: newPriceCents,
      termMonths,
      termPromoPercent,
      annualDiscountPct,
      monthsRemaining: remainingMonths(new Date(expiresAt), Date.now()),
    });
  }

  const prorate = target ? estimateProrate(target.priceCents) : 0;
  // Exact wallet/card split — identical math to lib/actions-server.ts resizeServer,
  // so the numbers shown here are what actually gets charged. (The server recomputes
  // the proration authoritatively; this drives the copy + button.)
  const split = walletSplit({ dueCents: prorate, balanceCents: walletBalanceCents, useWallet });
  const walletApplied = split.walletApplied;
  const cardCents = split.cardCents;

  return (
    <div className="space-y-5">
      {error && (
        <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-3 text-sm text-red-400">
          {error}
        </div>
      )}
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
        {plans.map((p) => {
          const current = p.id === currentPlanId;
          const tooSmall = p.diskGB < currentDiskGB;
          const active = selected === p.id;
          return (
            <button
              key={p.id}
              type="button"
              disabled={current || tooSmall || pending || disabled}
              title={
                tooSmall
                  ? `Disk can only grow — this plan has ${p.diskGB} GB, your server uses a ${currentDiskGB} GB disk.`
                  : undefined
              }
              onClick={() => setSelected(active ? null : p.id)}
              className={`card p-4 text-left transition-all ${
                current
                  ? "border-brand-400/60 ring-1 ring-brand-400/60"
                  : tooSmall
                    ? "cursor-not-allowed opacity-40"
                    : active
                      ? "cursor-pointer border-accent-blue ring-1 ring-accent-blue"
                      : "cursor-pointer hover:border-white/20"
              }`}
            >
              <div className="flex items-baseline justify-between">
                <span className="font-semibold">{p.name}</span>
                <span className="text-lg font-bold">{fmtMoney(p.priceCents)}<span className="text-xs font-normal text-slate-400">/mo</span></span>
              </div>
              <p className="mt-1 text-sm text-slate-400">
                {p.cpuCores} vCPU · {p.ramMB / 1024} GB RAM ·{" "}
                {p.diskGB + extraDiskGB} GB NVMe · {p.bandwidthTB} TB
              </p>
              {extraDiskGB > 0 && !tooSmall && (
                <p className="mt-1 text-[11px] text-slate-500">
                  {p.diskGB} GB plan + your {extraDiskGB} GB added storage
                </p>
              )}
              {current && <p className="mt-2 text-xs font-semibold text-brand-300">Current plan</p>}
              {tooSmall && <p className="mt-2 text-xs text-slate-500">Smaller disk — unavailable</p>}
            </button>
          );
        })}
      </div>

      <div className="space-y-3 rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-3">
        {target && prorate > 0 && walletBalanceCents > 0 && (
          <label className="flex items-center justify-between gap-3 text-xs text-slate-300">
            <span className="flex items-center gap-2">
              <input type="checkbox" checked={useWallet} onChange={(e) => setUseWallet(e.target.checked)} />
              Apply my balance ({fmtMoney(walletBalanceCents)})
            </span>
            <span className="text-slate-500">{useWallet ? "applied" : "off"}</span>
          </label>
        )}
        <div className="flex flex-wrap items-center justify-between gap-3">
          <p className="text-xs text-slate-400">
            {target && prorate > 0 ? (
              <>
                Prorated upgrade charge:{" "}
                <span className="font-semibold">{fmtMoney(prorate)}</span> for the rest of your term
                {walletApplied > 0 && <> — <span className="font-semibold text-emerald-300">{fmtMoney(walletApplied)}</span> from your wallet</>}
                {cardCents > 0 ? <> and <span className="font-semibold">{fmtMoney(cardCents)}</span> by secure card checkout</> : <> (nothing due on card)</>}.
                {split.clampedForStripeMin && <> Card payments have a {fmtMoney(STRIPE_MIN_CENTS)} minimum, so {fmtMoney(cardCents)} goes on the card.</>}
                {/* Whole charge is under the card floor: the wallet is the only way
                    to settle it, so say that instead of showing a wallet figure the
                    balance may not actually cover (see lib/wallet-split.ts). */}
                {split.belowStripeMin && (
                  walletBalanceCents >= prorate ? (
                    <> That&apos;s under the {fmtMoney(STRIPE_MIN_CENTS)} card minimum, so it comes out of your wallet balance.</>
                  ) : (
                    <> That&apos;s under the {fmtMoney(STRIPE_MIN_CENTS)} card minimum, so it can only come from your wallet — top up to at least {fmtMoney(prorate)} first.</>
                  )
                )}
                {" "}Requires a power cycle.
              </>
            ) : (
              "Upgrading requires a power cycle. The new price applies at your next renewal."
            )}
            {extraDiskGB > 0 && (
              <>
                {" "}
                Your {extraDiskGB} GB of added storage carries over to the new plan and keeps billing
                separately — it isn&apos;t part of this charge.
              </>
            )}
          </p>
          <button
            className="btn-primary"
            disabled={!target || pending || disabled}
            onClick={() => {
              if (!target) return;
              if (
                !window.confirm(
                  `Upgrade this server to ${target.name} (${fmtMoney(target.priceCents)}/mo)? The server will be power-cycled.`
                )
              )
                return;
              start(async () => {
                setError(null);
                const res = await resizeServer(serverId, target.id, useWallet);
                // Card portion > 0 → the action returns an embedded Stripe session
                // we mount in a modal on THIS page (no redirect).
                if (res?.checkout) {
                  setCheckout(res.checkout);
                  return;
                }
                if (res?.error) setError(res.error);
                else setSelected(null);
              });
            }}
          >
            {pending
              ? "Upgrading…"
              : !target
                ? "Select a plan"
                : cardCents > 0
                  ? `Continue to payment — ${fmtMoney(cardCents)}`
                  : prorate > 0
                    ? `Upgrade to ${target.name} — ${fmtMoney(walletApplied)}`
                    : `Upgrade to ${target.name}`}
          </button>
        </div>
      </div>
      {checkout && (
        <StripeCheckoutModal
          clientSecret={checkout.clientSecret}
          publishableKey={checkout.publishableKey}
          title="Complete your upgrade"
          onClose={() => setCheckout(null)}
        />
      )}
    </div>
  );
}

