/**
 * Shared post-provision SHARED-HOSTING upgrade core — the money path for growing a
 * live hosting account's storage or moving it UP to a bigger plan, WITHOUT the
 * order wizard. Plain server module (NOT "use server"), deliberately shaped
 * line-for-line like lib/resize.ts + lib/disk-expand.ts so the VPS and hosting
 * money paths can never drift apart.
 *
 * Two products, one discipline:
 *   • STORAGE  — buy N more GB of disk on top of the plan allowance. Prorated over
 *                the remaining term at the SAME per-GB/mo rate VPS extra disk uses;
 *                raises `extraDiskGB` + `diskQuotaMB`; re-applies the node quota.
 *                ADD-ONLY, exactly like Server.extraDiskGB (no shrink anywhere).
 *   • PLAN     — Starter → Pro (UP only). Prorated PLAN-price difference over the
 *                remaining term; raises `planId` + `diskQuotaMB`/`maxSites`/
 *                `maxDatabases` to the new plan; re-applies quota + FPM limits.
 *
 * Used by the wallet flow (lib/actions-hosting.ts expandHostingStorage /
 * upgradeHostingPlan) AND by the Stripe fulfilment path (lib/fulfil-checkout.ts) so
 * a paid embedded checkout applies the change immediately. Both callers price
 * through the SAME `*Quote` function, so displayed === charged.
 *
 * ─── WHY THIS CANNOT DOUBLE-CHARGE ──────────────────────────────────────────
 *  1. The `*Quote` function is the ONLY place the prorated amount is computed, and
 *     both the wallet path and the Stripe-confirm path call it.
 *  2. The wallet is debited exactly once, inside the same $transaction that mutates
 *     the account + enqueues the APPLY_PLAN_LIMITS task — a rolled-back debit leaves
 *     the account unchanged and no task.
 *  3. On the card path the wallet is NOT touched until Stripe clears: checkout
 *     charges only the card remainder, the confirm route credits that remainder to
 *     the wallet and then debits the FULL proration (encoded as chargeCents), so the
 *     two net out.
 *  4. `creditCheckoutSession`'s UNIQUE(stripeSessionId) + `FulfilledSession` make
 *     the confirm route idempotent — a replayed confirm URL applies nothing twice.
 *
 * ─── QUOTA + EXTRA DISK INTERACTION ─────────────────────────────────────────
 * `HostingAccount.diskQuotaMB` ALWAYS already folds in `extraDiskGB` — it is
 * `(plan.diskGB + extraDiskGB) × 1024`. So every recompute here derives the quota
 * from `effectiveDiskGB(plan.diskGB, extraDiskGB)` and the node's setquota
 * (taskApplyPlanLimits) never needs to know the add-on exists. A plan upgrade
 * therefore PRESERVES the customer's purchased extra disk in the new quota — it is
 * NOT dropped (the bug the naïve `newPlan.diskGB * 1024` would introduce).
 *
 * ─── SANDBOX ────────────────────────────────────────────────────────────────
 * The DB mutation (planId / diskQuotaMB / extraDiskGB / maxSites / maxDatabases)
 * happens HERE, in the charge transaction — never in the worker — so the panel
 * reflects the upgrade immediately in dev and prod alike. The worker's
 * APPLY_PLAN_LIMITS task only enacts the node-level setquota/FPM change (a no-op the
 * SANDBOX sweep simply marks DONE).
 */
import { db } from "./db";
import { debitWallet, InsufficientBalanceError } from "./wallet";
import { invoiceCreateData } from "./invoices";
import { remainingMonths, prorateUpgradeCents } from "./proration";
import { annualDiscountPct } from "./annual-discount";
import { extraDiskPerGbCents } from "./disk-expand";
import {
  EXTRA_DISK_MAX_TOTAL_GB,
  effectiveDiskGB,
  extraDiskCentsAt,
  extraDiskLabel,
  extraDiskProrateCents,
  isValidExtraDiskAddGB,
  maxAddableExtraDiskGB,
} from "./extra-disk";

export class HostingUpgradeError extends Error {}

function loadAccount(accountId: string) {
  return db.hostingAccount.findUnique({ where: { id: accountId }, include: { plan: true } });
}
type QuotedAccount = NonNullable<Awaited<ReturnType<typeof loadAccount>>>;

/** True when an APPLY_PLAN_LIMITS task is already queued/running for this account —
 *  the analog of the VPS "one in-flight job" guard, shared by BOTH upgrade kinds so
 *  a storage add and a plan change (or two of either) can't race a double charge. */
async function planLimitsInFlight(accountId: string): Promise<boolean> {
  const n = await db.hostingTask.count({
    where: { accountId, kind: "APPLY_PLAN_LIMITS" as any, status: { in: ["PENDING", "RUNNING"] } },
  });
  return n > 0;
}

// ───────────────────────────── STORAGE ──────────────────────────────────────

export type HostingStorageQuote = {
  account: QuotedAccount;
  /** GB being added in THIS purchase. */
  addGB: number;
  /** `extraDiskGB` the account will hold after this purchase. */
  targetExtraDiskGB: number;
  /** Effective disk (plan + extra) after the expansion, in GB. */
  newTotalDiskGB: number;
  perGbCents: number;
  /** Recurring monthly cost of the newly-added GB (billed every renewal). */
  monthlyCents: number;
  /** One-off charge for the remainder of the CURRENT paid term. */
  prorateCents: number;
};

/**
 * Validate a storage expansion + compute the prorated charge over the ACTUAL
 * remaining term (monthly extra-disk cost × every remaining month; null expiresAt
 * on comped accounts => 0). Identical maths to `diskExpandQuote`. Throws
 * HostingUpgradeError with a user-facing message on any guard failure. Does NOT
 * check ownership — callers must do that.
 */
export async function hostingStorageQuote(accountId: string, addGB: number): Promise<HostingStorageQuote> {
  const account = await loadAccount(accountId);
  if (!account) throw new HostingUpgradeError("Account not found.");
  if (account.status !== "ACTIVE") throw new HostingUpgradeError("The account is still being set up.");
  if (!isValidExtraDiskAddGB(addGB)) {
    throw new HostingUpgradeError("Choose an amount of storage to add.");
  }
  const targetExtraDiskGB = account.extraDiskGB + addGB;
  const newTotalDiskGB = effectiveDiskGB(account.plan.diskGB, targetExtraDiskGB);
  if (newTotalDiskGB > EXTRA_DISK_MAX_TOTAL_GB) {
    throw new HostingUpgradeError(
      `Storage tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB — this would take it to ${newTotalDiskGB} GB. Contact support for more.`,
    );
  }

  const perGbCents = await extraDiskPerGbCents();
  const monthlyCents = extraDiskCentsAt(addGB, perGbCents);
  // Prorated over the remaining term — the SAME two shared functions the client
  // "Add storage" control displays through (extra-disk.ts), so what the customer
  // agreed to and what is debited here cannot be two derivations of one idea.
  let prorateCents = 0;
  if (account.expiresAt) {
    prorateCents = extraDiskProrateCents(monthlyCents, remainingMonths(account.expiresAt, Date.now()));
  }
  return { account, addGB, targetExtraDiskGB, newTotalDiskGB, perGbCents, monthlyCents, prorateCents };
}

/**
 * Apply a storage expansion: (optionally) debit the wallet for the prorated charge,
 * record the wallet transaction + PAID invoice, RAISE `extraDiskGB`/`diskQuotaMB`,
 * and enqueue the APPLY_PLAN_LIMITS task that re-applies setquota on the node.
 * Re-validates every guard so it is safe to call from the unauthenticated confirm
 * route. Throws HostingUpgradeError on any guard failure.
 *
 * `chargeCents` overrides the recomputed proration — the paid path passes the exact
 * amount the customer paid into their wallet at checkout so the debit here nets to
 * zero against that credit (mirrors lib/disk-expand.ts applyDiskExpand).
 */
export async function applyHostingStorageExpand(opts: {
  accountId: string;
  addGB: number;
  actorUserId: string;
  chargeCents?: number;
}): Promise<void> {
  const q = await hostingStorageQuote(opts.accountId, opts.addGB);
  const { account, addGB, targetExtraDiskGB, newTotalDiskGB, monthlyCents } = q;
  const prorateCents = opts.chargeCents ?? q.prorateCents;

  if (await planLimitsInFlight(account.id)) {
    throw new HostingUpgradeError("Another upgrade is already being applied — wait for it to finish.");
  }

  const label = extraDiskLabel(addGB);
  try {
    await db.$transaction(async (tx) => {
      if (prorateCents > 0) {
        await debitWallet(tx, account.userId, prorateCents);
        await tx.walletTransaction.create({
          data: {
            userId: account.userId,
            amountCents: -prorateCents,
            description: `${label} (prorated) — ${account.primaryDomain}`,
          },
        });
        await tx.invoice.create({
          data: invoiceCreateData({
            userId: account.userId,
            description: `${label} (prorated) — ${account.primaryDomain}`,
            status: "PAID",
            lineItems: [
              {
                description:
                  `${label} — prorated for remaining term (${account.primaryDomain}). ` +
                  `Disk grows to ${newTotalDiskGB} GB permanently; renews at $${(monthlyCents / 100).toFixed(2)}/mo.`,
                qty: 1,
                unitCents: prorateCents,
                amountCents: prorateCents,
              },
            ],
          }),
        });
      }
      // Raise the account's stored fields in the SAME tx as the charge. The quota
      // folds in the new extra disk (effectiveDiskGB) so the node's setquota needs
      // no add-on awareness. Advancing extraDiskGB here (not in the worker) is what
      // makes the panel reflect the new capacity immediately, in dev and prod.
      await tx.hostingAccount.update({
        where: { id: account.id },
        data: { extraDiskGB: targetExtraDiskGB, diskQuotaMB: newTotalDiskGB * 1024 },
      });
      await tx.hostingTask.create({
        data: { accountId: account.id, kind: "APPLY_PLAN_LIMITS" as any },
      });
      await tx.auditLog.create({
        data: {
          userId: opts.actorUserId,
          action: "hosting.storage_expand",
          detail: `${account.id} +${addGB}GB -> extra=${targetExtraDiskGB} total=${newTotalDiskGB} prorate=${prorateCents}`,
        },
      });
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) {
      throw new HostingUpgradeError("Insufficient balance — top up your wallet first.");
    }
    throw e;
  }
}

// ────────────────────────────── PLAN ────────────────────────────────────────

export type HostingPlanQuote = {
  account: QuotedAccount;
  newPlan: NonNullable<Awaited<ReturnType<typeof db.hostingPlan.findUnique>>>;
  /** New effective disk (new plan allowance + existing extra), in GB. */
  newTotalDiskGB: number;
  /** One-off prorated PLAN-price difference for the remaining term. */
  prorateCents: number;
};

/**
 * Validate an UP-only plan change + compute the prorated PLAN-price difference over
 * the remaining term, priced at the account's sold term rate (annual discount
 * snapshot). Reuses `prorateUpgradeCents` — the SAME audited proration the VPS
 * resize charges — with no seasonal promo (hosting was never sold one). Throws
 * HostingUpgradeError on any guard failure. Does NOT check ownership.
 *
 * Storage add-on is untouched: `extraDiskGB` is additive to whichever plan the
 * account is on, so the prorated PLAN delta neither double-charges it (same GB
 * before/after) nor loses it (folded back into the new quota below).
 */
export async function hostingPlanQuote(accountId: string, newPlanId: string): Promise<HostingPlanQuote> {
  const account = await loadAccount(accountId);
  if (!account) throw new HostingUpgradeError("Account not found.");
  if (account.status !== "ACTIVE") throw new HostingUpgradeError("The account is still being set up.");
  const cur = account.plan;
  const newPlan = await db.hostingPlan.findUnique({ where: { id: newPlanId } });
  if (!newPlan || !newPlan.active) throw new HostingUpgradeError("That plan isn’t available.");
  if (newPlan.id === account.planId) throw new HostingUpgradeError("You’re already on this plan.");
  // Up-only guard (re-checked server-side; never trust the client's picker).
  // Disk can only grow (a smaller quota would ask setquota to SHRINK a live
  // filesystem) and price can only rise (a downgrade needs a refund path we don't
  // have). Require at least one to strictly increase so it's a real upgrade.
  if (newPlan.diskGB < cur.diskGB) {
    throw new HostingUpgradeError("Storage can only grow — choose a plan with equal or larger disk.");
  }
  if (newPlan.priceCents < cur.priceCents) {
    throw new HostingUpgradeError("Downgrades aren’t self-service yet — please contact support.");
  }
  if (newPlan.priceCents === cur.priceCents && newPlan.diskGB === cur.diskGB) {
    throw new HostingUpgradeError("That plan isn’t an upgrade.");
  }

  const newTotalDiskGB = effectiveDiskGB(newPlan.diskGB, account.extraDiskGB);
  let prorateCents = 0;
  if (account.expiresAt) {
    prorateCents = prorateUpgradeCents({
      fromMonthlyCents: cur.priceCents,
      toMonthlyCents: newPlan.priceCents,
      termMonths: account.termMonths,
      // Hosting carries no seasonal per-term promo (unlike VPS termPromoPercent):
      // 0 = price the delta at full list, term-discount only. Passing null here
      // would fall through to deepestPromoPercent() and UNDERCHARGE by ~45%.
      termPromoPercent: 0,
      // The annual rate this account was SOLD at (frozen at order), falling back to
      // the live setting for legacy rows — so a 12-month account's upgrade prices
      // against the same rate its order + renewals use. Harmless on monthly terms.
      annualDiscountPct: account.annualDiscountPct ?? (await annualDiscountPct()),
      monthsRemaining: remainingMonths(account.expiresAt, Date.now()),
    });
  }
  return { account, newPlan, newTotalDiskGB, prorateCents };
}

/**
 * Apply a plan upgrade: (optionally) debit the wallet for the prorated difference,
 * record the wallet transaction + PAID invoice, set `planId` and raise
 * `diskQuotaMB`/`maxSites`/`maxDatabases` to the new plan (PRESERVING purchased
 * extra disk in the quota), and enqueue APPLY_PLAN_LIMITS to re-apply quota + FPM
 * limits on the node. Re-validates every guard so it is safe from the confirm
 * route. Throws HostingUpgradeError on any guard failure.
 *
 * `chargeCents` overrides the recomputed proration — the paid path passes the exact
 * amount credited to the wallet at checkout so the debit here nets to zero against
 * it (mirrors lib/resize.ts applyResize).
 *
 * The renewal date (`expiresAt`) is intentionally left unchanged: this moves the
 * customer to a bigger plan for the rest of the term they already bought; future
 * terms bill at the new plan price (worker/product-renewals.ts reads planId).
 */
export async function applyHostingPlanUpgrade(opts: {
  accountId: string;
  newPlanId: string;
  actorUserId: string;
  chargeCents?: number;
}): Promise<void> {
  const q = await hostingPlanQuote(opts.accountId, opts.newPlanId);
  const { account, newPlan, newTotalDiskGB } = q;
  const prorateCents = opts.chargeCents ?? q.prorateCents;
  const cur = account.plan;

  if (await planLimitsInFlight(account.id)) {
    throw new HostingUpgradeError("Another upgrade is already being applied — wait for it to finish.");
  }

  try {
    await db.$transaction(async (tx) => {
      if (prorateCents > 0) {
        await debitWallet(tx, account.userId, prorateCents);
        await tx.walletTransaction.create({
          data: {
            userId: account.userId,
            amountCents: -prorateCents,
            description: `Web Hosting upgrade: ${cur.name} → ${newPlan.name} (prorated) — ${account.primaryDomain}`,
          },
        });
        await tx.invoice.create({
          data: invoiceCreateData({
            userId: account.userId,
            description: `Web Hosting upgrade: ${cur.name} → ${newPlan.name} (prorated) — ${account.primaryDomain}`,
            status: "PAID",
            lineItems: [
              {
                description: `Upgrade to ${newPlan.name} — prorated for remaining term (${account.primaryDomain})`,
                qty: 1,
                unitCents: prorateCents,
                amountCents: prorateCents,
              },
            ],
          }),
        });
      }
      // Snapshot the new plan's limits onto the account (as orderHostingAccount does
      // at creation) so a later admin plan edit can't silently re-quota this account.
      // The quota folds in the customer's purchased extra disk so it survives the
      // upgrade. phpVersion is left as-is: an upgrade only widens the allowed set.
      await tx.hostingAccount.update({
        where: { id: account.id },
        data: {
          planId: newPlan.id,
          diskQuotaMB: newTotalDiskGB * 1024,
          maxSites: newPlan.maxSites,
          maxDatabases: newPlan.maxDatabases,
        },
      });
      await tx.hostingTask.create({
        data: { accountId: account.id, kind: "APPLY_PLAN_LIMITS" as any },
      });
      await tx.auditLog.create({
        data: {
          userId: opts.actorUserId,
          action: "hosting.plan_upgrade",
          detail: `${account.id} ${cur.slug} -> ${newPlan.slug} prorate=${prorateCents}`,
        },
      });
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) {
      throw new HostingUpgradeError("Insufficient balance — top up your wallet first.");
    }
    throw e;
  }
}

/** Largest storage add still under the effective-disk ceiling (for the UI). */
export function hostingMaxAddableGB(planDiskGB: number, extraDiskGB: number): number {
  return maxAddableExtraDiskGB(planDiskGB, extraDiskGB);
}

