 * STORAGE expansion. Structurally identical to createDiskExpandCheckout: the CARD is
 * charged only `cardCents` (the wallet-split remainder) while the FULL proration
 * travels in metadata as `chargeCents`, so the confirm route debits the whole
 * proration back out of the wallet against the just-credited card amount. The wallet
 * is never touched before the card clears.
 */
export async function createHostingStorageCheckout(
  user: { id: string; email: string },
  cardCents: number,
  expand: { accountId: string; addGB: number; domain?: string; prorateCents: number },
): Promise<EmbeddedCheckout | null> {
  if (!stripeConfigured() || cardCents <= 0) return null;
  const base = process.env.APP_URL ?? "http://localhost:3000";
  const session = await stripe().checkout.sessions.create({
    mode: "payment",
    customer_email: user.email,
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: {
            name: `Nxeon Hosting +${expand.addGB} GB storage${expand.domain ? ` — ${expand.domain}` : ""}`,
            // The one-way nature is on the Stripe page itself, not just in our UI.
            description: "Permanent storage expansion — disk space can be added but never removed.",
          },
          unit_amount: cardCents,
        },
        quantity: 1,
      },
    ],
    metadata: {
      nxeonUserId: user.id,
      // chargeCents = the FULL proration to debit on confirm (not the card amount).
      nxeonHostingStorage: packMetadata("Hosting storage intent", {
        accountId: expand.accountId,
        addGB: expand.addGB,
        chargeCents: expand.prorateCents,
      }),
    },
    // Embedded modal on our page; return_url is the same fulfilling confirm route.
    ui_mode: EMBEDDED_UI_MODE,
    return_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
  }, EMBEDDED_REQUEST_OPTS);
  return session.client_secret
    ? { clientSecret: session.client_secret, publishableKey: stripePublishableKey() }
    : null;
}

