export type UpgradePlanView = {
  id: string;
  name: string;
  priceCents: number;
  diskGB: number;
  maxSites: number;
  maxDatabases: number;
  bandwidthTB: number;
  tagline: string;
  /** PRORATED price difference over the remaining term — the amount charged now. */
  deltaCents: number;
};

/**
 * Everything the post-provision upgrade UI (storage + plan) needs, in ONE fetch so
 * the two self-contained controls read a consistent snapshot. Owner or admin.
 *
 * `plans[].deltaCents` is the PRORATED plan-price difference for the remaining term
 * (via lib/hosting-upgrade.ts hostingPlanQuote maths), so what the picker shows is
 * what expandHostingStorage/upgradeHostingPlan charge — the server still recomputes
 * authoritatively before taking a cent.
 */
export type HostingUpgradeContext = {
  error?: string;
  domain?: string;
  walletBalanceCents?: number;
  currentPlanName?: string;
  currentPlanId?: string;
  currentDiskGB?: number;
  currentPriceCents?: number;
  extraDiskGB?: number;
  expiresAt?: string | null;
  /** Extra-storage price per GB/month (for the storage control's estimate). */
  pricePerGbCents?: number;
  /** Largest storage add still under the effective-disk ceiling; 0 = at the cap. */
  maxAddGB?: number;
  plans?: UpgradePlanView[];
};

export async function getHostingUpgradeContext(accountId: string): Promise<HostingUpgradeContext> {
  const user = await requireUser();
  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, include: { plan: true } });
  if (!a) return { error: "Account not found." };
  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  const cur = a.plan;
  const extraDiskGB = a.extraDiskGB ?? 0;
  const perGbCents = await extraDiskPerGbCents();
  const annualPct = a.annualDiscountPct ?? (await annualDiscountPct());
  const monthsRemaining = remainingMonths(a.expiresAt, Date.now());

  const all = await db.hostingPlan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } });
  const plans: UpgradePlanView[] = all
    .filter(
      (p) =>
        p.id !== cur.id &&
        p.priceCents >= cur.priceCents &&
        p.diskGB >= cur.diskGB &&
        (p.priceCents > cur.priceCents || p.diskGB > cur.diskGB),
    )
    .map((p) => ({
      id: p.id,
      name: p.name,
      priceCents: p.priceCents,
      diskGB: p.diskGB,
      maxSites: p.maxSites,
      maxDatabases: p.maxDatabases,
      bandwidthTB: p.bandwidthTB,
      tagline: p.tagline,
      // Prorated PLAN-price delta over the remaining term at the account's sold rate
      // (no seasonal promo). SAME maths lib/hosting-upgrade.ts charges — one source.
      deltaCents: a.expiresAt
        ? prorateUpgradeCents({
            fromMonthlyCents: cur.priceCents,
            toMonthlyCents: p.priceCents,
            termMonths: a.termMonths,
            termPromoPercent: 0,
            annualDiscountPct: annualPct,
            monthsRemaining,
          })
        : 0,
    }));

  return {
    domain: a.primaryDomain,
    walletBalanceCents: user.balanceCents,
    currentPlanName: cur.name,
    currentPlanId: cur.id,
    currentDiskGB: cur.diskGB,
    currentPriceCents: cur.priceCents,
    extraDiskGB,
    expiresAt: a.expiresAt?.toISOString() ?? null,
    pricePerGbCents: perGbCents,
    maxAddGB: hostingMaxAddableGB(cur.diskGB, extraDiskGB),
    plans,
  };
}

/**
 * Post-provision "Add storage" for a live hosting account: buy N more GB of disk on
 * top of the plan allowance, prorated over the remaining term. MIRRORS the VPS
 * expandServerDisk money flow EXACTLY — quote → walletSplit → (card remainder ?
 * embedded Stripe checkout : apply now). Storage is ONE-WAY (add only), like VPS.
 *
 * Returns `{ checkout }` when a card leg remains (mount it in StripeCheckoutModal);
 * `{ ok: true }` when the wallet covered it (or nothing was due); `{ error }` otherwise.
 */
export async function expandHostingStorage(
  accountId: string,
  addGB: number,
  useWallet: boolean = true,
): Promise<HostingResult & { checkout?: EmbeddedCheckout }> {
  // Spend path: block wallet debits while an admin is impersonating.
  await assertNotImpersonating();
  const user = await requireUser();
  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true } });
  if (!a) return { error: "Account not found." };
  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  // Purchase gate: an irreversible charge.
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };

  // Round DOWN to a purchasable amount — a malformed value can only ever cost less.
  const gb = normalizeExtraDiskGB(addGB);
  if (gb <= 0) return { error: "Choose an amount of storage to add." };

  // Validate + price the expansion (ownership already checked above).
  let quote;
  try {
    quote = await hostingStorageQuote(accountId, gb);
  } catch (e) {
    if (e instanceof HostingUpgradeError) return { error: e.message };
    throw e;
  }
  const { prorateCents } = quote;

  // Wallet-aware split — identical logic to the deploy/resize flows, so displayed
  // === charged (the storage control computes the same walletSplit client-side).
  const { cardCents } = walletSplit({ dueCents: prorateCents, balanceCents: user.balanceCents, useWallet });

  // Card portion > 0 → charge ONLY the remainder on the card; the confirm route
  // credits it to the wallet and debits the FULL proration (chargeCents), so the
  // wallet absorbs its share and the card the rest — wallet never touched first.
  if (cardCents > 0) {
    const checkout = await createHostingStorageCheckout(user, cardCents, {
      accountId,
      addGB: gb,
      domain: quote.account.primaryDomain,
      prorateCents,
    });
    if (!checkout) {
      return {
        error: `Adding ${gb} GB costs $${(prorateCents / 100).toFixed(2)} for the rest of your term, and card payments aren’t set up — top up your wallet first.`,
      };
    }
    return { checkout };
  }

  // Card portion is $0 (wallet covers it, or the charge is $0) → apply now, debiting
  // the full proration from the wallet.
  try {
    await applyHostingStorageExpand({ accountId, addGB: gb, actorUserId: user.id });
  } catch (e) {
    if (e instanceof HostingUpgradeError) return { error: e.message };
    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
    throw e;
  }
  revalidatePath(`/dashboard/hosting/${accountId}`);
  return { ok: true };
}

/**
 * Move a hosting account UP to a larger plan (Starter → Pro). MIRRORS the VPS
 * resizeServer money flow EXACTLY — quote (prorated PLAN-price difference over the
 * remaining term) → walletSplit → (card remainder ? embedded Stripe checkout : apply
 * now). UP only: a downgrade is rejected (no refund path). The renewal date is
 * unchanged; future terms bill at the new plan price.
 *
 * Returns `{ checkout }` when a card leg remains; `{ ok: true }` on a wallet-only
 * (or $0) upgrade; `{ error }` otherwise.
 */
export async function upgradeHostingPlan(
  accountId: string,
  newPlanId: string,
  useWallet: boolean = true,
): Promise<HostingResult & { checkout?: EmbeddedCheckout }> {
  // Spend path: block wallet debits while an admin is impersonating — this was the
  // one hosting charge an impersonating admin could otherwise put on the customer.
  await assertNotImpersonating();
  const user = await requireUser();
  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true } });
  if (!a) return { error: "Account not found." };
  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };

  // Validate up-only + price the upgrade (ownership already checked above).
  let quote;
  try {
    quote = await hostingPlanQuote(accountId, newPlanId);
  } catch (e) {
    if (e instanceof HostingUpgradeError) return { error: e.message };
    throw e;
  }
  const { newPlan, prorateCents } = quote;

  const { cardCents } = walletSplit({ dueCents: prorateCents, balanceCents: user.balanceCents, useWallet });

  if (cardCents > 0) {
    const checkout = await createHostingPlanUpgradeCheckout(user, cardCents, {
      accountId,
      newPlanId,
      planName: newPlan.name,
      domain: quote.account.primaryDomain,
      prorateCents,
    });
    if (!checkout) {
      return {
        error: `Upgrading costs $${(prorateCents / 100).toFixed(2)} for the rest of your term, and card payments aren’t set up — top up your wallet first.`,
      };
    }
    return { checkout };
  }

  try {
    await applyHostingPlanUpgrade({ accountId, newPlanId, actorUserId: user.id });
  } catch (e) {
    if (e instanceof HostingUpgradeError) return { error: e.message };
    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
    throw e;
  }
  revalidatePath(`/dashboard/hosting/${accountId}`);
  return { ok: true };
}

