"use client";

import { useEffect, useState, useTransition } from "react";
import {
  expandHostingStorage,
  upgradeHostingPlan,
  getHostingUpgradeContext,
  type HostingUpgradeContext,
  type UpgradePlanView,
} from "@/lib/actions-hosting";
import { StripeCheckoutModal } from "@/components/customer/StripeCheckoutModal";
import { fmtMoney } from "@/components/ui/primitives";
import { walletSplit, STRIPE_MIN_CENTS } from "@/lib/wallet-split";
import { remainingMonths } from "@/lib/proration";
import {
  EXTRA_DISK_MIN_GB,
  EXTRA_DISK_ONE_WAY_NOTE,
  EXTRA_DISK_STEP_GB,
  effectiveDiskGB,
  extraDiskCentsAt,
  extraDiskProrateCents,
} from "@/lib/extra-disk";

type Checkout = { clientSecret: string; publishableKey: string };

/**
 * Post-provision hosting upgrades — self-contained so the hosting-panel restructure
 * and the Email rework can proceed independently. Wired into HostingTabs' Settings
 * tab with a single `<HostingUpgradePanel accountId=… />`.
 *
 * Fetches one consistent snapshot (getHostingUpgradeContext) and renders two
 * controls that MIRROR the VPS equivalents exactly:
 *   • AddStorageCard  ← components/customer/AddStorage.tsx (VPS extra disk)
 *   • PlanUpgradeCard ← components/customer/ResizePicker.tsx (VPS resize)
 * Both hand the wallet/card split to lib/wallet-split.ts and, on a card leg, mount
 * the SAME embedded StripeCheckoutModal — no bespoke payment path.
 */
export function HostingUpgradePanel({ accountId }: { accountId: string }) {
  const [ctx, setCtx] = useState<HostingUpgradeContext | null>(null);

  function reload() {
    getHostingUpgradeContext(accountId)
      .then((c) => setCtx(c))
      .catch(() => setCtx({ error: "Couldn’t load upgrade options." }));
  }
  useEffect(() => {
    reload();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [accountId]);

  if (ctx === null) return <p className="text-xs text-slate-500">Loading upgrade options…</p>;
  if (ctx.error) return <p className="text-xs text-amber-300">{ctx.error}</p>;

  return (
    <div className="space-y-6">
      <PlanUpgradeCard ctx={ctx} accountId={accountId} />
      <AddStorageCard ctx={ctx} accountId={accountId} />
    </div>
  );
}

/* ------------------------------------------------------- Plan upgrade ------ */

function PlanUpgradeCard({ ctx, accountId }: { ctx: HostingUpgradeContext; accountId: string }) {
  const plans = ctx.plans ?? [];
  const walletBalanceCents = ctx.walletBalanceCents ?? 0;
  const [selected, setSelected] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [checkout, setCheckout] = useState<Checkout | null>(null);
  const [useWallet, setUseWallet] = useState(walletBalanceCents > 0);
  const [pending, start] = useTransition();

  const target = plans.find((p) => p.id === selected) ?? null;
  // Prorated charge comes straight from the server context (single source of truth);
  // the split is computed here from the SAME walletSplit the action uses.
  const prorate = target ? target.deltaCents : 0;
  const split = walletSplit({ dueCents: prorate, balanceCents: walletBalanceCents, useWallet });
  const { walletApplied, cardCents } = split;

  if (plans.length === 0) {
    return (
      <div>
        <p className="mb-1 text-sm font-medium text-slate-300">Upgrade your plan</p>
        <p className="text-xs text-slate-500">You’re on our largest plan — nothing bigger to move up to.</p>
      </div>
    );
  }

  return (
    <div>
      <p className="mb-1 text-sm font-medium text-slate-300">Upgrade your plan</p>
      <p className="mb-3 text-xs text-slate-500">
        Move up to a larger plan for the rest of your term. You’re charged only the prorated price
        difference now; your renewal date doesn’t change, and future terms bill at the new plan price.
      </p>

      {error && (
        <div className="mb-3 rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-3 text-sm text-red-400">
          {error}
        </div>
      )}

      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
        {plans.map((p: UpgradePlanView) => {
          const active = selected === p.id;
          return (
            <button
              key={p.id}
              type="button"
              disabled={pending}
              onClick={() => setSelected(active ? null : p.id)}
              className={`card p-4 text-left transition-all ${
                active ? "cursor-pointer border-accent-blue ring-1 ring-accent-blue" : "cursor-pointer hover:border-white/20"
              }`}
            >
              <div className="flex items-baseline justify-between">
                <span className="font-semibold">{p.name}</span>
                <span className="text-lg font-bold">
                  {fmtMoney(p.priceCents)}
                  <span className="text-xs font-normal text-slate-400">/mo</span>
                </span>
              </div>
              <p className="mt-1 text-sm text-slate-400">
                {p.diskGB} GB · {p.maxSites} site{p.maxSites === 1 ? "" : "s"} · {p.maxDatabases} database
                {p.maxDatabases === 1 ? "" : "s"} · {p.bandwidthTB} TB
              </p>
              {p.tagline && <p className="mt-1 text-[11px] text-slate-500">{p.tagline}</p>}
              {p.deltaCents > 0 && (
                <p className="mt-2 text-xs font-semibold text-brand-300">+{fmtMoney(p.deltaCents)} now</p>
              )}
            </button>
          );
        })}
      </div>

      <div className="mt-4 space-y-3 rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-3">
        {target && prorate > 0 && walletBalanceCents > 0 && (
          <label className="flex items-center justify-between gap-3 text-xs text-slate-300">
            <span className="flex items-center gap-2">
              <input type="checkbox" checked={useWallet} onChange={(e) => setUseWallet(e.target.checked)} />
              Apply my balance ({fmtMoney(walletBalanceCents)})
            </span>
            <span className="text-slate-500">{useWallet ? "applied" : "off"}</span>
          </label>
        )}
        <div className="flex flex-wrap items-center justify-between gap-3">
          <p className="text-xs text-slate-400">
            {target && prorate > 0 ? (
              <>
                Prorated upgrade charge: <span className="font-semibold">{fmtMoney(prorate)}</span> for the rest of
                your term
                {walletApplied > 0 && (
                  <> — <span className="font-semibold text-emerald-300">{fmtMoney(walletApplied)}</span> from your wallet</>
                )}
                {cardCents > 0 ? (
                  <> and <span className="font-semibold">{fmtMoney(cardCents)}</span> by secure card checkout</>
                ) : (
                  <> (nothing due on card)</>
                )}
                .
                {split.clampedForStripeMin && (
                  <> Card payments have a {fmtMoney(STRIPE_MIN_CENTS)} minimum, so {fmtMoney(cardCents)} goes on the card.</>
                )}
                {split.belowStripeMin &&
                  (walletBalanceCents >= prorate ? (
                    <> That’s under the {fmtMoney(STRIPE_MIN_CENTS)} card minimum, so it comes out of your wallet balance.</>
                  ) : (
                    <> That’s under the {fmtMoney(STRIPE_MIN_CENTS)} card minimum, so it can only come from your wallet — top up to at least {fmtMoney(prorate)} first.</>
                  ))}
                {ctx.extraDiskGB && ctx.extraDiskGB > 0 ? (
                  <> Your {ctx.extraDiskGB} GB of added storage carries over and keeps billing separately — it isn’t part of this charge.</>
                ) : null}
              </>
            ) : target ? (
              "Nothing due now for this change. The new plan applies immediately."
            ) : (
              "Select a plan to see the prorated upgrade charge."
            )}
          </p>
          <button
            className="btn-primary"
            disabled={!target || pending}
            onClick={() => {
              if (!target) return;
              if (
                !window.confirm(
                  `Upgrade to ${target.name} (${fmtMoney(target.priceCents)}/mo)?` +
                    (prorate > 0 ? `\n\nDue now: ${fmtMoney(prorate)} — prorated for the rest of your term.` : ""),
                )
              )
                return;
              start(async () => {
                setError(null);
                const res = await upgradeHostingPlan(accountId, target.id, useWallet);
                // Card leg → mount the embedded Stripe modal on THIS page (no redirect).
                if (res?.checkout) {
                  setCheckout(res.checkout);
                  return;
                }
                if (res?.error) setError(res.error);
                else setTimeout(() => window.location.reload(), 700);
              });
            }}
          >
            {pending
              ? "Upgrading…"
              : !target
                ? "Select a plan"
                : cardCents > 0
                  ? `Continue to payment — ${fmtMoney(cardCents)}`
                  : prorate > 0
                    ? `Upgrade to ${target.name} — ${fmtMoney(walletApplied)}`
                    : `Upgrade to ${target.name}`}
          </button>
        </div>
      </div>

      {checkout && (
        <StripeCheckoutModal
          clientSecret={checkout.clientSecret}
          publishableKey={checkout.publishableKey}
          title="Complete your plan upgrade"
          onClose={() => setCheckout(null)}
        />
      )}
    </div>
  );
}

/* -------------------------------------------------------- Add storage ------ */

function AddStorageCard({ ctx, accountId }: { ctx: HostingUpgradeContext; accountId: string }) {
  const planDiskGB = ctx.currentDiskGB ?? 0;
  const extraDiskGB = ctx.extraDiskGB ?? 0;
  const pricePerGbCents = ctx.pricePerGbCents ?? 0;
  const maxAdd = ctx.maxAddGB ?? 0;
  const walletBalanceCents = ctx.walletBalanceCents ?? 0;
  const expiresAt = ctx.expiresAt ?? null;

  const [addGB, setAddGB] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [checkout, setCheckout] = useState<Checkout | null>(null);
  const [useWallet, setUseWallet] = useState(walletBalanceCents > 0);
  const [pending, start] = useTransition();

  const currentTotal = effectiveDiskGB(planDiskGB, extraDiskGB);
  const newTotal = currentTotal + addGB;
  const monthlyCents = extraDiskCentsAt(addGB, pricePerGbCents);
  // Estimated prorated charge — from the SAME two shared functions the server
  // charges through (lib/extra-disk.ts), never a private copy of the arithmetic.
  const prorate = !expiresAt ? 0 : extraDiskProrateCents(monthlyCents, remainingMonths(new Date(expiresAt), Date.now()));
  const split = walletSplit({ dueCents: prorate, balanceCents: walletBalanceCents, useWallet });
  const { walletApplied, cardCents } = split;

  return (
    <div>
      <div className="mb-1 flex flex-wrap items-center justify-between gap-2">
        <p className="text-sm font-medium text-slate-300">Add storage</p>
        <span className="text-xs text-slate-400">{fmtMoney(pricePerGbCents)}/GB/mo</span>
      </div>
      <p className="mb-3 text-xs text-slate-500">
        Grow this account’s disk without changing its plan. Currently{" "}
        <span className="font-semibold text-slate-300">{currentTotal} GB</span>
        {extraDiskGB > 0 && (
          <span className="text-slate-500">
            {" "}
            ({planDiskGB} GB plan + {extraDiskGB} GB added)
          </span>
        )}
        .
      </p>

      {error && (
        <div className="mb-3 rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-3 text-sm text-red-400">
          {error}
        </div>
      )}

      {maxAdd <= 0 ? (
        <p className="text-xs text-slate-500">This account is at the maximum disk size. Contact support for larger volumes.</p>
      ) : (
        <>
          <div className="flex items-center gap-3">
            <input
              type="range"
              className="flex-1 accent-brand-400"
              min={0}
              max={maxAdd}
              step={EXTRA_DISK_STEP_GB}
              value={addGB}
              aria-label="Storage to add in GB"
              disabled={pending}
              onChange={(e) => setAddGB(Number(e.target.value))}
            />
            <div className="flex shrink-0 gap-1.5">
              {[10, 50, 100, 250].filter((g) => g <= maxAdd).map((g) => (
                <button
                  type="button"
                  key={g}
                  disabled={pending}
                  onClick={() => setAddGB(addGB === g ? 0 : g)}
                  className={`rounded-full px-2.5 py-1 text-[11px] font-semibold transition ${
                    addGB === g ? "bg-white text-navy-950" : "bg-white/[0.06] text-slate-300 hover:bg-white/10"
                  }`}
                >
                  +{g}
                </button>
              ))}
            </div>
          </div>
          <p className="mt-2 text-[11px] text-slate-500">
            {EXTRA_DISK_MIN_GB}–{maxAdd} GB in {EXTRA_DISK_STEP_GB} GB steps.
          </p>

          <div className="mt-3 rounded-xl border border-amber-500/25 bg-amber-500/10 px-4 py-3 text-xs text-amber-300">
            {EXTRA_DISK_ONE_WAY_NOTE}
          </div>

          <div className="mt-3 space-y-3 rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-3">
            {addGB > 0 && prorate > 0 && walletBalanceCents > 0 && (
              <label className="flex items-center justify-between gap-3 text-xs text-slate-300">
                <span className="flex items-center gap-2">
                  <input type="checkbox" checked={useWallet} onChange={(e) => setUseWallet(e.target.checked)} />
                  Apply my balance ({fmtMoney(walletBalanceCents)})
                </span>
                <span className="text-slate-500">{useWallet ? "applied" : "off"}</span>
              </label>
            )}
            <div className="flex flex-wrap items-center justify-between gap-3">
              <p className="text-xs text-slate-400">
                {addGB > 0 ? (
                  <>
                    Disk grows to <span className="font-semibold text-slate-200">{newTotal} GB</span> and adds{" "}
                    <span className="font-semibold">{fmtMoney(monthlyCents)}/mo</span> to every renewal.
                    {prorate > 0 ? (
                      <>
                        {" "}
                        Due now: <span className="font-semibold">{fmtMoney(prorate)}</span> for the rest of your term
                        {walletApplied > 0 && (
                          <> — <span className="font-semibold text-emerald-300">{fmtMoney(walletApplied)}</span> from your wallet</>
                        )}
                        {cardCents > 0 ? (
                          <> and <span className="font-semibold">{fmtMoney(cardCents)}</span> by secure card checkout</>
                        ) : (
                          <> (nothing due on card)</>
                        )}
                        .
                        {split.clampedForStripeMin && (
                          <> Card payments have a {fmtMoney(STRIPE_MIN_CENTS)} minimum, so {fmtMoney(cardCents)} goes on the card.</>
                        )}
                        {split.belowStripeMin &&
                          (walletBalanceCents >= prorate ? (
                            <> That’s under the {fmtMoney(STRIPE_MIN_CENTS)} card minimum, so it comes out of your wallet balance.</>
                          ) : (
                            <> That’s under the {fmtMoney(STRIPE_MIN_CENTS)} card minimum, so it can only come from your wallet — top up to at least {fmtMoney(prorate)} first.</>
                          ))}
                      </>
                    ) : (
                      <> Nothing due now.</>
                    )}
                  </>
                ) : (
                  "Choose how much storage to add."
                )}
              </p>
              <button
                className="btn-primary"
                disabled={addGB <= 0 || pending}
                onClick={() => {
                  if (addGB <= 0) return;
                  if (
                    !window.confirm(
                      `Add ${addGB} GB to ${ctx.domain ?? "this account"}, taking its disk to ${newTotal} GB?\n\n` +
                        `This is PERMANENT — storage can be added but never removed, and it adds ${fmtMoney(monthlyCents)}/mo to every renewal.` +
                        (prorate > 0 ? `\n\nDue now: ${fmtMoney(prorate)} for the rest of your term.` : ""),
                    )
                  )
                    return;
                  start(async () => {
                    setError(null);
                    const res = await expandHostingStorage(accountId, addGB, useWallet);
                    if (res?.checkout) {
                      setCheckout(res.checkout);
                      return;
                    }
                    if (res?.error) setError(res.error);
                    else setTimeout(() => window.location.reload(), 700);
                  });
                }}
              >
                {pending
                  ? "Adding storage…"
                  : addGB <= 0
                    ? "Choose an amount"
                    : cardCents > 0
                      ? `Continue to payment — ${fmtMoney(cardCents)}`
                      : prorate > 0
                        ? `Add ${addGB} GB permanently — ${fmtMoney(walletApplied)}`
                        : `Add ${addGB} GB permanently`}
              </button>
            </div>
          </div>
        </>
      )}

      {checkout && (
        <StripeCheckoutModal
          clientSecret={checkout.clientSecret}
          publishableKey={checkout.publishableKey}
          title="Complete your storage upgrade"
          onClose={() => setCheckout(null)}
        />
      )}
    </div>
  );
}

