import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { packMetadata, STRIPE_METADATA_VALUE_MAX } from "../lib/stripe.ts";

/**
 * Stripe metadata is where this platform keeps the only record of WHAT a payment
 * was for. Everything here defends one property: a session is never created
 * carrying a payload the confirm route cannot read back.
 */

function code(relative: string): string {
  return readFileSync(new URL(relative, import.meta.url), "utf8")
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/^\s*\/\/.*$/gm, "");
}

/* ------------------------------------------------------------------ *
 * A truncated intent used to become a silent wallet top-up
 *
 * Every payload was written as `JSON.stringify(x).slice(0, 490)`. A slice through
 * JSON is not JSON, the consumer's JSON.parse throws inside a try that returns
 * null, and fulfilCheckoutSession then cannot see an order/resize/disk-expansion
 * in the session — so it takes its plain top-up branch. Card charged, money in
 * the wallet, NO server, no error, no failure row. Invisible from every surface.
 * ------------------------------------------------------------------ */

test("an oversized payload is refused, never truncated", () => {
  const huge = { hostname: "x".repeat(STRIPE_METADATA_VALUE_MAX) };
  assert.throws(

256	test("every fulfilment failure that captured money notifies the customer", () => {
257	  // Resize and disk-expansion used to settle FAILED silently: the money sat in the
258	  // wallet and the only surface that said so was a database row.
259	  assert.equal(
260	    (FULFIL.match(/notifyStalled\(/g) ?? []).length,
261	    6, // definition + unreadable + order + gameOrder + resize + diskExpand
262	    "each captured-but-unfulfilled branch must notify",
263	  );
264	});
